3	import jakarta.servlet.http.HttpServletRequest;
4	import java.net.URI;
5	import java.util.ArrayList;
6	import java.util.List;
7	import org.slf4j.Logger;
8	import org.slf4j.LoggerFactory;
9	import org.springframework.http.HttpHeaders;
10	import org.springframework.http.HttpStatus;
11	import org.springframework.http.HttpStatusCode;
12	import org.springframework.http.ProblemDetail;
13	import org.springframework.http.ResponseEntity;
14	import org.springframework.lang.Nullable;
15	import org.springframework.web.HttpMediaTypeNotAcceptableException;
16	import org.springframework.web.HttpMediaTypeNotSupportedException;
17	import org.springframework.web.HttpRequestMethodNotSupportedException;
18	import org.springframework.web.bind.MethodArgumentNotValidException;
19	import org.springframework.web.bind.MissingRequestHeaderException;
20	import org.springframework.web.bind.annotation.ExceptionHandler;
21	import org.springframework.web.bind.annotation.RestControllerAdvice;
22	import org.springframework.web.context.request.ServletWebRequest;
23	import org.springframework.web.context.request.WebRequest;
24	import org.springframework.web.method.annotation.HandlerMethodValidationException;
25	import org.springframework.web.servlet.NoHandlerFoundException;
26	import org.springframework.web.servlet.mvc.method.annotation.ResponseEntityExceptionHandler;
27	import org.springframework.web.servlet.resource.NoResourceFoundException;
28	
29	/** Renders every error as application/problem+json with the urn:problem:order-payment:{slug} type. */
30	@RestControllerAdvice
31	public class GlobalExceptionHandler extends ResponseEntityExceptionHandler {
32	
33	    private static final Logger log = LoggerFactory.getLogger(GlobalExceptionHandler.class);
34	
35	    @ExceptionHandler(ApiException.class)
36	    public ResponseEntity<Object> handleApiException(ApiException ex, HttpServletRequest request) {
37	        ProblemType type = ex.type();
38	        ProblemDetail pd = problem(type, type.status(), ex.getMessage(), request.getRequestURI());
39	        ex.extensions().forEach(pd::setProperty);
40	        return ResponseEntity.status(type.status()).headers(ex.headers()).body(pd);
41	    }
42	
43	    @ExceptionHandler(Exception.class)
44	    public ResponseEntity<Object> handleUnexpected(Exception ex, HttpServletRequest request) {
45	        log.error("Unexpected error on {}", request.getRequestURI(), ex);
46	        ProblemDetail pd = problem(ProblemType.INTERNAL_ERROR, HttpStatus.INTERNAL_SERVER_ERROR,
47	                "Unexpected error", request.getRequestURI());
48	        return ResponseEntity.status(HttpStatus.INTERNAL_SERVER_ERROR).body(pd);
49	    }
50	
51	    @Override
52	    protected ResponseEntity<Object> handleExceptionInternal(Exception ex, @Nullable Object body, HttpHeaders headers,
53	                                                             HttpStatusCode statusCode, WebRequest request) {
54	        String path = request instanceof ServletWebRequest swr ? swr.getRequest().getRequestURI() : "";
55	        ProblemType type = typeFor(ex, statusCode);
56	        ProblemDetail pd = problem(type, statusCode, detailFor(type), path);
57	        if (ex instanceof MethodArgumentNotValidException manve) {
58	            List<FieldErrorDetail> errors = new ArrayList<>();
59	            manve.getBindingResult().getFieldErrors()
60	                    .forEach(fe -> errors.add(new FieldErrorDetail(fe.getField(), fe.getDefaultMessage())));
61	            manve.getBindingResult().getGlobalErrors()
62	                    .forEach(ge -> errors.add(new FieldErrorDetail(ge.getObjectName(), ge.getDefaultMessage())));
63	            pd.setProperty("errors", errors);
64	        } else if (ex instanceof HandlerMethodValidationException hmve) {
65	            List<FieldErrorDetail> errors = new ArrayList<>();
66	            hmve.getParameterValidationResults().forEach(r -> r.getResolvableErrors().forEach(e ->
67	                    errors.add(new FieldErrorDetail(r.getMethodParameter().getParameterName(), e.getDefaultMessage()))));
68	            pd.setProperty("errors", errors);
69	        } else if (ex instanceof MissingRequestHeaderException mrhe) {
70	            pd.setProperty("header", mrhe.getHeaderName());
71	        }
72	        if (statusCode.is5xxServerError()) {
73	            log.error("Server error on {}", path, ex);
74	        }
75	        return super.handleExceptionInternal(ex, pd, headers, statusCode, request);
76	    }
77	
78	    private static ProblemType typeFor(Exception ex, HttpStatusCode status) {
79	        if (ex instanceof MethodArgumentNotValidException || ex instanceof HandlerMethodValidationException) {
80	            return ProblemType.VALIDATION_FAILED;
81	        }
82	        if (ex instanceof MissingRequestHeaderException) {
83	            return ProblemType.MISSING_HEADER;
84	        }
85	        if (ex instanceof NoResourceFoundException || ex instanceof NoHandlerFoundException) {
86	            return ProblemType.RESOURCE_NOT_FOUND;
87	        }
88	        if (ex instanceof HttpRequestMethodNotSupportedException) {
89	            return ProblemType.METHOD_NOT_ALLOWED;
90	        }
91	        if (ex instanceof HttpMediaTypeNotSupportedException) {
92	            return ProblemType.UNSUPPORTED_MEDIA_TYPE;
93	        }
94	        if (ex instanceof HttpMediaTypeNotAcceptableException) {
95	            return ProblemType.NOT_ACCEPTABLE;
96	        }
97	        if (status.is5xxServerError()) {
98	            return ProblemType.INTERNAL_ERROR;
99	        }
100	        return ProblemType.MALFORMED_REQUEST;
101	    }
102	
103	    private static String detailFor(ProblemType type) {
104	        return switch (type) {
105	            case VALIDATION_FAILED -> "Request validation failed";
106	            case MISSING_HEADER -> "A required header is missing";
107	            case RESOURCE_NOT_FOUND -> "No resource is mapped to this path";
108	            case METHOD_NOT_ALLOWED -> "The HTTP method is not allowed for this path";
109	            case UNSUPPORTED_MEDIA_TYPE -> "The request Content-Type is not supported";
110	            case NOT_ACCEPTABLE -> "The requested response media type is not available";
111	            case INTERNAL_ERROR -> "Unexpected error";
112	            default -> "The request is malformed (invalid JSON, missing body or a value of the wrong type)";
113	        };
114	    }
115	
116	    private static ProblemDetail problem(ProblemType type, HttpStatusCode status, String detail, String instance) {
117	        ProblemDetail pd = ProblemDetail.forStatusAndDetail(status, detail);
118	        pd.setType(URI.create(type.typeUri()));
119	        pd.setTitle(type.title());
120	        if (instance != null && !instance.isEmpty()) {
121	            try {
122	                pd.setInstance(URI.create(instance));
123	            } catch (IllegalArgumentException ignored) {
124	                // unparsable raw path: leave instance unset rather than failing the error response
125	            }
126	        }
127	        return pd;
128	    }
129	}
