2	
3	import com.example.order.common.FieldErrorDetail;
4	import com.example.order.common.Problems;
5	import com.example.order.common.Times;
6	import java.time.Clock;
7	import java.util.ArrayList;
8	import java.util.List;
9	import org.springframework.dao.DataIntegrityViolationException;
10	import org.springframework.stereotype.Service;
11	import org.springframework.transaction.annotation.Transactional;
12	
13	@Service
14	public class CouponService {
15	
16	    private static final String UNIQUE_CODE_CONSTRAINT = "uk_coupons_code";
17	
18	    private final CouponRepository coupons;
19	    private final Clock clock;
20	
21	    public CouponService(CouponRepository coupons, Clock clock) {
22	        this.coupons = coupons;
23	        this.clock = clock;
24	    }
25	
26	    @Transactional
27	    public CouponResponse create(CreateCouponRequest r) {
28	        validateCrossField(r);
29	        if (coupons.existsByCode(r.code())) {
30	            throw Problems.couponCodeDuplicate(r.code());
31	        }
32	        Coupon coupon = new Coupon(r.code(), r.type(), r.value(),
33	                r.minOrderAmount() == null ? 0L : r.minOrderAmount(), r.maxDiscountAmount(),
34	                r.totalQuantity(), r.validFrom(), r.validUntil(), Times.now(clock));
35	        try {
36	            return CouponResponse.from(coupons.saveAndFlush(coupon));
37	        } catch (DataIntegrityViolationException e) {
38	            Throwable cause = e.getMostSpecificCause();
39	            String message = cause.getMessage() == null ? "" : cause.getMessage();
40	            if (message.contains(UNIQUE_CODE_CONSTRAINT)) {
41	                throw Problems.couponCodeDuplicate(r.code());
42	            }
43	            throw e;
44	        }
45	    }
46	
47	    @Transactional(readOnly = true)
48	    public CouponResponse get(String code) {
49	        return coupons.findByCode(code).map(CouponResponse::from).orElseThrow(() -> Problems.couponNotFound(code));
50	    }
51	
52	    private static void validateCrossField(CreateCouponRequest r) {
53	        List<FieldErrorDetail> errors = new ArrayList<>();
54	        if (r.type() == CouponType.RATE && r.value() > 100) {
55	            errors.add(new FieldErrorDetail("value", "RATE coupon value must be within 1..100"));
56	        }
57	        if (!r.validFrom().isBefore(r.validUntil())) {
58	            errors.add(new FieldErrorDetail("validUntil", "validFrom must be before validUntil"));
59	        }
60	        if (!errors.isEmpty()) {
61	            throw Problems.validationFailed(errors);
62	        }
63	    }
64	}
