3	import com.example.order.common.Problems;
4	import java.nio.charset.StandardCharsets;
5	import java.util.Base64;
6	import java.util.regex.Pattern;
7	
8	/** Opaque cursor: Base64URL(no padding) of "v1:" + lastId. */
9	public final class Cursor {
10	
11	    private static final Pattern PAYLOAD = Pattern.compile("^v1:[1-9][0-9]{0,18}$");
12	
13	    private Cursor() {
14	    }
15	
16	    public static String encode(long lastId) {
17	        return Base64.getUrlEncoder().withoutPadding().encodeToString(("v1:" + lastId).getBytes(StandardCharsets.UTF_8));
18	    }
19	
20	    public static long decode(String cursor) {
21	        try {
22	            byte[] raw = Base64.getUrlDecoder().decode(cursor);
23	            String payload = new String(raw, StandardCharsets.UTF_8);
24	            if (!PAYLOAD.matcher(payload).matches()) {
25	                throw Problems.invalidCursor();
26	            }
27	            long id = Long.parseLong(payload.substring(3));
28	            if (!encode(id).equals(cursor)) { // reject non-canonical encodings
29	                throw Problems.invalidCursor();
30	            }
31	            return id;
32	        } catch (IllegalArgumentException e) { // bad base64 or Long overflow
33	            throw Problems.invalidCursor();
34	        }
35	    }
36	}
