10	import java.util.Optional;
11	import java.util.UUID;
12	import org.springframework.jdbc.core.RowMapper;
13	import org.springframework.jdbc.core.simple.JdbcClient;
14	import org.springframework.stereotype.Repository;
15	
16	/**
17	 * All order persistence goes through conditional UPDATEs (status + lease guards, 02_db_design.md section 3).
18	 * Plain JDBC on purpose: no persistence-context staleness between a claim and the follow-up read.
19	 */
20	@Repository
21	public class OrderRepository {
22	
23	    private static final String COLUMNS = "id, user_id, status, coupon_id, coupon_code, subtotal, discount, "
24	            + "total_price, idempotency_key, request_hash, created_at, expires_at, paid_at, shipped_at, "
25	            + "delivered_at, lease_kind, lease_token, lease_expires_at";
26	
27	    private static final String NO_ACTIVE_LEASE = "(lease_token IS NULL OR lease_expires_at <= :now)";
28	    private static final String CLEAR_LEASE = "lease_kind = NULL, lease_token = NULL, lease_expires_at = NULL";
29	
30	    private static final RowMapper<OrderRow> ORDER_MAPPER = (rs, n) -> mapOrder(rs);
31	
32	    private final JdbcClient jdbc;
33	
34	    public OrderRepository(JdbcClient jdbc) {
35	        this.jdbc = jdbc;
36	    }
37	
38	    private static OrderRow mapOrder(ResultSet rs) throws SQLException {
39	        return new OrderRow(
40	                rs.getLong("id"),
41	                rs.getString("user_id"),
42	                OrderStatus.valueOf(rs.getString("status")),
43	                rs.getObject("coupon_id", Long.class),
44	                rs.getString("coupon_code"),
45	                rs.getLong("subtotal"),
46	                rs.getLong("discount"),
47	                rs.getLong("total_price"),
48	                rs.getString("idempotency_key"),
49	                rs.getString("request_hash"),
50	                Times.instant(rs, "created_at"),
51	                Times.instant(rs, "expires_at"),
52	                Times.instant(rs, "paid_at"),
53	                Times.instant(rs, "shipped_at"),
54	                Times.instant(rs, "delivered_at"),
55	                rs.getString("lease_kind"),
56	                rs.getObject("lease_token", UUID.class),
57	                Times.instant(rs, "lease_expires_at"));
58	    }
59	
60	    // ---------- reads ----------
61	
62	    public Optional<OrderRow> findById(long id) {
63	        return jdbc.sql("SELECT " + COLUMNS + " FROM orders WHERE id = :id")
64	                .param("id", id).query(ORDER_MAPPER).optional();
65	    }
66	
67	    public Optional<OrderRow> findByUserAndKey(String userId, String idempotencyKey) {
68	        return jdbc.sql("SELECT " + COLUMNS + " FROM orders WHERE user_id = :u AND idempotency_key = :k")
69	                .param("u", userId).param("k", idempotencyKey).query(ORDER_MAPPER).optional();
70	    }
71	
72	    public List<OrderItemRow> findItems(Collection<Long> orderIds) {
73	        if (orderIds.isEmpty()) {
74	            return List.of();
75	        }
76	        return jdbc.sql("SELECT order_id, line_no, product_id, quantity, unit_price FROM order_items "
