90	        if (status != null) {
91	            sql.append(" AND status = :status");
92	        }
93	        if (beforeId != null) {
94	            sql.append(" AND id < :beforeId");
95	        }
96	        sql.append(" ORDER BY id DESC LIMIT :limit");
97	        JdbcClient.StatementSpec spec = jdbc.sql(sql.toString()).param("limit", limit);
98	        if (userId != null) {
99	            spec = spec.param("userId", userId);
100	        }
101	        if (status != null) {
102	            spec = spec.param("status", status.name());
