113	                + "AND expires_at <= :now AND " + NO_ACTIVE_LEASE);
114	        if (userId != null) {
115	            sql.append(" AND user_id = :userId");
116	        }
117	        sql.append(" ORDER BY expires_at LIMIT :limit");
