167	
168	    /** (7) expire claim. */
169	    public int claimExpire(long id, Instant now) {
170	        OrderStatus.requireTransition(OrderStatus.PENDING_PAYMENT, OrderStatus.EXPIRED);
171	        return jdbc.sql("UPDATE orders SET status = 'EXPIRED', updated_at = :now, version = version + 1 "
172	                        + "WHERE id = :id AND status = 'PENDING_PAYMENT' AND expires_at <= :now AND "
173	                        + NO_ACTIVE_LEASE)
174	                .param("id", id).param("now", Times.ts(now)).update();
175	    }
