177	    /** (8) cancel claim for a pending order. */
178	    public int claimCancel(long id, Instant now) {
179	        OrderStatus.requireTransition(OrderStatus.PENDING_PAYMENT, OrderStatus.CANCELLED);
180	        return jdbc.sql("UPDATE orders SET status = 'CANCELLED', updated_at = :now, version = version + 1 "
181	                        + "WHERE id = :id AND status = 'PENDING_PAYMENT' AND expires_at > :now AND "
182	                        + NO_ACTIVE_LEASE)
183	                .param("id", id).param("now", Times.ts(now)).update();
184	    }
