186	    /** (9) payment lease. */
187	    public int claimPayLease(long id, UUID token, Instant now, Instant leaseUntil) {
188	        return jdbc.sql("UPDATE orders SET lease_kind = 'PAY', lease_token = :t, lease_expires_at = :until, "
189	                        + "updated_at = :now, version = version + 1 "
190	                        + "WHERE id = :id AND status = 'PENDING_PAYMENT' AND expires_at > :now AND "
191	                        + NO_ACTIVE_LEASE)
