197	    public int completePayment(long id, OrderStatus target, UUID token, Instant now) {
198	        OrderStatus.requireTransition(OrderStatus.PENDING_PAYMENT, target);
199	        String paidAt = target == OrderStatus.PAID ? ", paid_at = :now" : "";
200	        return jdbc.sql("UPDATE orders SET status = :target" + paidAt + ", " + CLEAR_LEASE
201	                        + ", updated_at = :now, version = version + 1 "
202	                        + "WHERE id = :id AND status = 'PENDING_PAYMENT' AND lease_token = :t")
203	                .param("target", target.name()).param("id", id).param("t", token).param("now", Times.ts(now))
204	                .update();
205	    }
