207	    /** (11) refund lease. */
208	    public int claimRefundLease(long id, UUID token, Instant now, Instant leaseUntil) {
209	        return jdbc.sql("UPDATE orders SET lease_kind = 'REFUND', lease_token = :t, lease_expires_at = :until, "
210	                        + "updated_at = :now, version = version + 1 "
211	                        + "WHERE id = :id AND status = 'PAID' AND " + NO_ACTIVE_LEASE)
212	                .param("id", id).param("t", token).param("until", Times.ts(leaseUntil))
213	                .param("now", Times.ts(now)).update();
214	    }
215	
216	    /** (12) refund completion; requires the lease token. */
217	    public int completeRefund(long id, UUID token, Instant now) {
218	        OrderStatus.requireTransition(OrderStatus.PAID, OrderStatus.REFUNDED);
219	        return jdbc.sql("UPDATE orders SET status = 'REFUNDED', " + CLEAR_LEASE
220	                        + ", updated_at = :now, version = version + 1 "
221	                        + "WHERE id = :id AND status = 'PAID' AND lease_token = :t")
222	                .param("id", id).param("t", token).param("now", Times.ts(now)).update();
223	    }
224	
225	    /** (13) ship claim. */
226	    public int claimShip(long id, Instant now) {
227	        OrderStatus.requireTransition(OrderStatus.PAID, OrderStatus.SHIPPED);
228	        return jdbc.sql("UPDATE orders SET status = 'SHIPPED', shipped_at = :now, updated_at = :now, "
229	                        + "version = version + 1 WHERE id = :id AND status = 'PAID' AND " + NO_ACTIVE_LEASE)
230	                .param("id", id).param("now", Times.ts(now)).update();
231	    }
232	
233	    /** (14) deliver claim. */
234	    public int claimDeliver(long id, Instant now) {
235	        OrderStatus.requireTransition(OrderStatus.SHIPPED, OrderStatus.DELIVERED);
236	        return jdbc.sql("UPDATE orders SET status = 'DELIVERED', delivered_at = :now, updated_at = :now, "
237	                        + "version = version + 1 WHERE id = :id AND status = 'SHIPPED'")
238	                .param("id", id).param("now", Times.ts(now)).update();
239	    }
240	
241	    /** (15) release only the lease (gateway failure); status untouched. */
242	    public int releaseLease(long id, UUID token, Instant now) {
243	        return jdbc.sql("UPDATE orders SET " + CLEAR_LEASE + ", updated_at = :now, version = version + 1 "
244	                        + "WHERE id = :id AND lease_token = :t")
245	                .param("id", id).param("t", token).param("now", Times.ts(now)).update();
246	    }
247	}
