8	import org.springframework.jdbc.core.simple.JdbcClient;
9	import org.springframework.stereotype.Repository;
10	
11	/**
12	 * Atomic conditional UPDATEs on products (02_db_design.md section 3 patterns 1-3). No SELECT-then-UPDATE.
13	 */
14	@Repository
15	public class StockRepository {
16	
17	    private final JdbcClient jdbc;
18	
19	    public StockRepository(JdbcClient jdbc) {
20	        this.jdbc = jdbc;
21	    }
22	
23	    /** id -> current price for the ids that exist. */
24	    public Map<Long, Long> findPrices(Collection<Long> ids) {
25	        Map<Long, Long> result = new HashMap<>();
26	        jdbc.sql("SELECT id, price FROM products WHERE id IN (:ids)")
27	                .param("ids", ids)
28	                .query((rs, n) -> {
29	                    result.put(rs.getLong("id"), rs.getLong("price"));
30	                    return null;
31	                }).list();
32	        return result;
33	    }
34	
35	    /** (1) reserve; false when stock - reserved < quantity. */
36	    public boolean reserve(long productId, int quantity, Instant now) {
37	        return jdbc.sql("UPDATE products SET reserved = reserved + :q, updated_at = :now "
38	                        + "WHERE id = :id AND stock - reserved >= :q")
39	                .param("q", quantity).param("now", Times.ts(now)).param("id", productId)
40	                .update() == 1;
41	    }
42	
43	    /** (2) release a reservation; false means the invariant was violated (caller must fail the transaction). */
44	    public boolean release(long productId, int quantity, Instant now) {
45	        return jdbc.sql("UPDATE products SET reserved = reserved - :q, updated_at = :now "
46	                        + "WHERE id = :id AND reserved >= :q")
47	                .param("q", quantity).param("now", Times.ts(now)).param("id", productId)
48	                .update() == 1;
49	    }
50	
51	    /** (3) ship: stock and reserved are decremented in one statement. */
52	    public boolean commitShip(long productId, int quantity, Instant now) {
53	        return jdbc.sql("UPDATE products SET stock = stock - :q, reserved = reserved - :q, updated_at = :now "
54	                        + "WHERE id = :id AND reserved >= :q AND stock >= :q")
55	                .param("q", quantity).param("now", Times.ts(now)).param("id", productId)
56	                .update() == 1;
57	    }
58	
59	    public int available(long productId) {
60	        return jdbc.sql("SELECT stock - reserved FROM products WHERE id = :id")
61	                .param("id", productId).query(Integer.class).optional().orElse(0);
62	    }
63	}
