1	package com.example.order.order;
2	
3	import com.example.order.common.Problems;
4	import com.example.order.common.Times;
5	import com.example.order.config.OrderPaymentProperties;
6	import com.example.order.coupon.Coupon;
7	import com.example.order.coupon.CouponRepository;
8	import com.example.order.coupon.CouponUsageRepository;
9	import com.example.order.coupon.DiscountCalculator;
10	import com.example.order.product.StockRepository;
11	import java.time.Clock;
12	import java.time.Instant;
13	import java.util.ArrayList;
14	import java.util.Comparator;
15	import java.util.List;
16	import java.util.Map;
17	import java.util.Optional;
18	import org.springframework.stereotype.Service;
19	import org.springframework.transaction.annotation.Transactional;
20	
21	/**
22	 * One transaction: order claim INSERT -> coupon rule pre-check -> stock reservation (id asc) -> coupon claim
23	 * -> items. Any failure rolls everything back (the idempotency key is then not consumed).
24	 */
25	@Service
26	public class OrderCreator {
27	
28	    private final OrderRepository orders;
29	    private final StockRepository stock;
30	    private final CouponRepository coupons;
31	    private final CouponUsageRepository couponUsage;
32	    private final OrderPaymentProperties props;
33	    private final Clock clock;
34	
35	    public OrderCreator(OrderRepository orders, StockRepository stock, CouponRepository coupons,
36	                        CouponUsageRepository couponUsage, OrderPaymentProperties props, Clock clock) {
37	        this.orders = orders;
38	        this.stock = stock;
39	        this.coupons = coupons;
40	        this.couponUsage = couponUsage;
41	        this.props = props;
42	        this.clock = clock;
43	    }
44	
45	    /** @return the new order id, or empty when the (user, key) pair already has an order (caller replays). */
46	    @Transactional
47	    public Optional<Long> create(String userId, String idempotencyKey, String requestHash, CreateOrderRequest request) {
48	        Instant now = Times.now(clock);
49	        List<CreateOrderRequest.Item> requested = request.items();
50	
51	        Map<Long, Long> prices = stock.findPrices(requested.stream().map(CreateOrderRequest.Item::productId).toList());
52	        long subtotal = 0;
53	        List<OrderItemRow> lines = new ArrayList<>();
54	        int lineNo = 1;
55	        for (CreateOrderRequest.Item item : requested) {
56	            Long price = prices.get(item.productId());
57	            if (price == null) {
58	                throw Problems.productNotFound(item.productId());
59	            }
60	            subtotal += price * item.quantity();
61	            lines.add(new OrderItemRow(0, lineNo++, item.productId(), item.quantity(), price));
62	        }
63	
64	        Coupon coupon = null;
65	        if (request.couponCode() != null) {
66	            coupon = coupons.findByCode(request.couponCode())
67	                    .orElseThrow(() -> Problems.couponNotFound(request.couponCode()));
68	        }
69	
70	        Optional<Long> inserted = orders.insertIfAbsent(userId, coupon == null ? null : coupon.getId(),
71	                coupon == null ? null : coupon.getCode(), subtotal, idempotencyKey, requestHash, now,
72	                now.plus(props.ttl()));
73	        if (inserted.isEmpty()) {
74	            return Optional.empty();
75	        }
76	        long orderId = inserted.get();
77	
78	        if (coupon != null) {
79	            precheckCoupon(coupon, subtotal, now);
80	        }
81	
82	        lines.stream().sorted(Comparator.comparingLong(OrderItemRow::productId)).forEach(line -> {
83	            if (!stock.reserve(line.productId(), line.quantity(), now)) {
84	                throw Problems.insufficientStock(line.productId(), line.quantity(), stock.available(line.productId()));
85	            }
86	        });
87	
88	        if (coupon != null) {
89	            if (!couponUsage.tryUse(coupon.getId(), now)) {
90	                boolean inPeriod = !now.isBefore(coupon.getValidFrom()) && !now.isAfter(coupon.getValidUntil());
91	                throw inPeriod ? Problems.couponExhausted(coupon.getCode())
92	                        : Problems.couponNotInPeriod(coupon.getCode());
93	            }
94	            long discount = DiscountCalculator.calculate(coupon, subtotal);
95	            orders.applyDiscount(orderId, discount, subtotal - discount, now);
96	        }
97	
98	        orders.insertItems(orderId, lines);
99	        return Optional.of(orderId);
100	    }
101	
102	    private static void precheckCoupon(Coupon coupon, long subtotal, Instant now) {
103	        if (now.isBefore(coupon.getValidFrom()) || now.isAfter(coupon.getValidUntil())) {
104	            throw Problems.couponNotInPeriod(coupon.getCode());
105	        }
106	        if (subtotal < coupon.getMinOrderAmount()) {
107	            throw Problems.couponMinOrderNotMet(coupon.getCode(), coupon.getMinOrderAmount(), subtotal);
108	        }
109	        if (coupon.getUsedCount() >= coupon.getTotalQuantity()) {
110	            throw Problems.couponExhausted(coupon.getCode());
111	        }
112	    }
113	}
