1	package com.example.order.order;
2	
3	import com.example.order.common.Hashing;
4	import com.example.order.common.Problems;
5	import com.example.order.payment.PaymentService;
6	import java.util.Comparator;
7	import java.util.Optional;
8	import java.util.stream.Collectors;
9	import org.springframework.stereotype.Service;
10	
11	/** Non-transactional orchestration: order creation idempotency loop and cancel dispatch. */
12	@Service
13	public class OrderCommandService {
14	
15	    private static final int MAX_CREATE_ATTEMPTS = 3;
16	
17	    public record CreateOutcome(OrderResponse order, boolean replayed) {
18	    }
19	
20	    private final OrderRepository orders;
21	    private final OrderCreator creator;
22	    private final OrderAssembler assembler;
23	    private final OrderTransitionService transitions;
24	    private final PaymentService payments;
25	
26	    public OrderCommandService(OrderRepository orders, OrderCreator creator, OrderAssembler assembler,
27	                               OrderTransitionService transitions, PaymentService payments) {
28	        this.orders = orders;
29	        this.creator = creator;
30	        this.assembler = assembler;
31	        this.transitions = transitions;
32	        this.payments = payments;
33	    }
34	
35	    public CreateOutcome create(String userId, String idempotencyKey, CreateOrderRequest request) {
36	        String hash = requestHash(request);
37	        for (int attempt = 0; attempt < MAX_CREATE_ATTEMPTS; attempt++) {
38	            Optional<OrderRow> existing = orders.findByUserAndKey(userId, idempotencyKey);
39	            if (existing.isPresent()) {
40	                if (!hash.equals(existing.get().requestHash())) {
41	                    throw Problems.idempotencyKeyConflict(
42	                            "The Idempotency-Key was already used with a different request body");
43	                }
44	                return new CreateOutcome(assembler.assemble(existing.get()), true);
45	            }
46	            Optional<Long> created = creator.create(userId, idempotencyKey, hash, request);
47	            if (created.isPresent()) {
48	                return new CreateOutcome(assembler.load(created.get()), false);
49	            }
50	            // a concurrent request with the same key committed first: loop to replay / conflict
51	        }
52	        throw new IllegalStateException("Could not resolve idempotent order creation");
53	    }
54	
55	    public OrderResponse cancel(long orderId) {
56	        OrderRow current = orders.findById(orderId).orElseThrow(() -> Problems.orderNotFound(orderId));
57	        if (current.status() == OrderStatus.PAID) {
58	            return payments.refund(orderId);
59	        }
60	        return transitions.cancelPending(orderId); // non-pending statuses are mapped to 409 inside
61	    }
62	
63	    public OrderResponse ship(long orderId) {
64	        return transitions.ship(orderId);
65	    }
66	
67	    public OrderResponse deliver(long orderId) {
68	        return transitions.deliver(orderId);
69	    }
70	
71	    /** SHA-256 of "items=<productId>:<qty>,...(productId asc);coupon=<code or empty>". */
72	    static String requestHash(CreateOrderRequest request) {
73	        String items = request.items().stream()
74	                .sorted(Comparator.comparingLong(CreateOrderRequest.Item::productId))
75	                .map(i -> i.productId() + ":" + i.quantity())
76	                .collect(Collectors.joining(","));
77	        return Hashing.sha256Hex("items=" + items + ";coupon=" + (request.couponCode() == null ? "" : request.couponCode()));
78	    }
79	}
