1	package com.example.order.order;
2	
3	import com.example.order.common.ApiException;
4	import com.example.order.common.Problems;
5	import com.example.order.common.Times;
6	import com.example.order.product.StockRepository;
7	import java.time.Clock;
8	import java.time.Instant;
9	import org.springframework.stereotype.Service;
10	import org.springframework.transaction.annotation.Transactional;
11	
12	/**
13	 * Transactional state transitions that need no PG call: expire, cancel(pending), ship, deliver.
14	 * Each transition is a conditional UPDATE (claim); side effects run only when the claim affected 1 row.
15	 */
16	@Service
17	public class OrderTransitionService {
18	
19	    private final OrderRepository orders;
20	    private final OrderAssembler assembler;
21	    private final ReservationReleaser releaser;
22	    private final StockRepository stock;
23	    private final Clock clock;
24	
25	    public OrderTransitionService(OrderRepository orders, OrderAssembler assembler, ReservationReleaser releaser,
26	                                  StockRepository stock, Clock clock) {
27	        this.orders = orders;
28	        this.assembler = assembler;
29	        this.releaser = releaser;
30	        this.stock = stock;
31	        this.clock = clock;
32	    }
33	
34	    /** Expires one order if (and only if) it is due and not under an active lease. Safe to call concurrently. */
35	    @Transactional
36	    public boolean expireIfDue(long orderId) {
37	        Instant now = Times.now(clock);
38	        if (orders.claimExpire(orderId, now) != 1) {
39	            return false;
40	        }
41	        releaser.release(orderId, now);
42	        return true;
43	    }
44	
45	    /** cancel on PENDING_PAYMENT. Keeps the lazy expiry commit when it then answers order-expired. */
46	    @Transactional(noRollbackFor = ApiException.class)
47	    public OrderResponse cancelPending(long orderId) {
48	        Instant now = Times.now(clock);
49	        OrderRow current = orders.findById(orderId).orElseThrow(() -> Problems.orderNotFound(orderId));
50	        if (current.status() != OrderStatus.PENDING_PAYMENT) {
51	            throw OrderStateMachine.failureFor(current, OrderAction.CANCEL, now);
52	        }
53	        if (!current.expiresAt().isAfter(now)) {
54	            expireIfDue(orderId);
55	            throw OrderStateMachine.failureFor(reload(orderId), OrderAction.CANCEL, now);
56	        }
57	        if (orders.claimCancel(orderId, now) != 1) {
58	            throw OrderStateMachine.failureFor(reload(orderId), OrderAction.CANCEL, now);
59	        }
60	        releaser.release(orderId, now);
61	        return assembler.load(orderId);
62	    }
63	
64	    @Transactional
65	    public OrderResponse ship(long orderId) {
66	        Instant now = Times.now(clock);
67	        if (orders.claimShip(orderId, now) != 1) {
68	            throw OrderStateMachine.failureFor(reload(orderId), OrderAction.SHIP, now);
69	        }
70	        for (OrderItemRow item : releaser.sortedItems(orderId)) {
71	            if (!stock.commitShip(item.productId(), item.quantity(), now)) {
72	                throw new IllegalStateException("Stock invariant violated shipping product " + item.productId()
73	                        + " for order " + orderId);
74	            }
75	        }
76	        return assembler.load(orderId);
77	    }
78	
79	    @Transactional
80	    public OrderResponse deliver(long orderId) {
81	        Instant now = Times.now(clock);
82	        if (orders.claimDeliver(orderId, now) != 1) {
83	            throw OrderStateMachine.failureFor(reload(orderId), OrderAction.DELIVER, now);
84	        }
85	        return assembler.load(orderId);
86	    }
87	
88	    private OrderRow reload(long orderId) {
89	        return orders.findById(orderId).orElseThrow(() -> Problems.orderNotFound(orderId));
90	    }
91	}
