1	package com.example.order.order;
2	
3	import com.example.order.common.ApiException;
4	import com.example.order.common.Problems;
5	import java.time.Instant;
6	
7	/**
8	 * Maps "a conditional UPDATE claimed 0 rows" to the 409 of 01_api_design.md section 3.3,
9	 * given the freshly re-read order.
10	 */
11	public final class OrderStateMachine {
12	
13	    private OrderStateMachine() {
14	    }
15	
16	    public static ApiException failureFor(OrderRow current, OrderAction action, Instant now) {
17	        boolean leaseActive = current.leaseActive(now);
18	        if (action == OrderAction.PAY || action == OrderAction.CANCEL) {
19	            if (current.status() == OrderStatus.EXPIRED) {
20	                return Problems.orderExpired(current.expiresAt());
21	            }
22	            if (current.status() == OrderStatus.PENDING_PAYMENT && !current.expiresAt().isAfter(now)) {
23	                return leaseActive
24	                        ? Problems.operationInProgress(current.leaseKind())
25	                        : Problems.orderExpired(current.expiresAt());
26	            }
27	        }
28	        if (leaseActive && action.canStartFrom(current.status())) {
29	            return Problems.operationInProgress(current.leaseKind());
30	        }
31	        return Problems.invalidOrderState(current.status(), action);
32	    }
33	}
