2	
3	import com.example.order.coupon.CouponUsageRepository;
4	import com.example.order.product.StockRepository;
5	import java.time.Instant;
6	import java.util.Comparator;
7	import java.util.List;
8	import org.springframework.stereotype.Component;
9	
10	/**
11	 * Gives back reserved stock and the coupon quantity. Must be called only inside the transaction whose
12	 * conditional UPDATE just won the claim (so it happens exactly once). Lock order: products(id asc) -> coupons.
13	 */
14	@Component
15	public class ReservationReleaser {
16	
17	    private final OrderRepository orders;
18	    private final StockRepository stock;
19	    private final CouponUsageRepository couponUsage;
20	
21	    public ReservationReleaser(OrderRepository orders, StockRepository stock, CouponUsageRepository couponUsage) {
22	        this.orders = orders;
23	        this.stock = stock;
24	        this.couponUsage = couponUsage;
25	    }
26	
27	    public void release(long orderId, Instant now) {
28	        OrderRow order = orders.findById(orderId)
29	                .orElseThrow(() -> new IllegalStateException("Order vanished during release: " + orderId));
30	        for (OrderItemRow item : sortedItems(orderId)) {
31	            if (!stock.release(item.productId(), item.quantity(), now)) {
32	                throw new IllegalStateException("Stock invariant violated releasing product " + item.productId()
33	                        + " for order " + orderId);
34	            }
35	        }
36	        if (order.couponId() != null && !couponUsage.release(order.couponId())) {
37	            throw new IllegalStateException("Coupon invariant violated releasing coupon " + order.couponId()
38	                    + " for order " + orderId);
39	        }
40	    }
41	
42	    public List<OrderItemRow> sortedItems(long orderId) {
43	        return orders.findItems(List.of(orderId)).stream()
44	                .sorted(Comparator.comparingLong(OrderItemRow::productId)).toList();
45	    }
46	}
