1	package com.example.order.order;
2	
3	import com.example.order.common.Problems;
4	import com.example.order.common.Times;
5	import java.time.Clock;
6	import java.time.Instant;
7	import java.util.List;
8	import org.slf4j.Logger;
9	import org.slf4j.LoggerFactory;
10	import org.springframework.stereotype.Service;
11	
12	/** Reads with lazy expiry: a due PENDING_PAYMENT order is really expired before it is shown. */
13	@Service
14	public class OrderQueryService {
15	
16	    private static final Logger log = LoggerFactory.getLogger(OrderQueryService.class);
17	    private static final int LAZY_SWEEP_LIMIT = 500;
18	
19	    private final OrderRepository orders;
20	    private final OrderAssembler assembler;
21	    private final OrderTransitionService transitions;
22	    private final Clock clock;
23	
24	    public OrderQueryService(OrderRepository orders, OrderAssembler assembler, OrderTransitionService transitions,
25	                             Clock clock) {
26	        this.orders = orders;
27	        this.assembler = assembler;
28	        this.transitions = transitions;
29	        this.clock = clock;
30	    }
31	
32	    public OrderResponse get(long id) {
33	        Instant now = Times.now(clock);
34	        OrderRow row = orders.findById(id).orElseThrow(() -> Problems.orderNotFound(id));
35	        if (row.status() == OrderStatus.PENDING_PAYMENT && !row.expiresAt().isAfter(now)
36	                && transitions.expireIfDue(id)) {
37	            row = orders.findById(id).orElseThrow(() -> Problems.orderNotFound(id));
38	        }
39	        return assembler.assemble(row);
40	    }
41	
42	    public OrderPage list(String userId, OrderStatus status, int size, Long beforeId) {
43	        Instant now = Times.now(clock);
44	        if (status == null || status == OrderStatus.PENDING_PAYMENT) {
45	            for (Long dueId : orders.findDueIds(now, userId, LAZY_SWEEP_LIMIT)) {
46	                try {
47	                    transitions.expireIfDue(dueId);
48	                } catch (RuntimeException e) {
49	                    log.warn("Lazy expiry failed for order {}", dueId, e);
50	                }
51	            }
52	        }
53	        List<OrderRow> rows = orders.list(userId, status, beforeId, size + 1);
54	        boolean hasMore = rows.size() > size;
55	        List<OrderRow> page = hasMore ? rows.subList(0, size) : rows;
56	        String next = hasMore ? Cursor.encode(page.get(page.size() - 1).id()) : null;
57	        return new OrderPage(assembler.assemble(page), next);
58	    }
59	}
