1	package com.example.order.payment;
2	
3	import com.example.order.common.Hashing;
4	import com.example.order.order.OrderResponse;
5	import java.util.UUID;
6	import org.slf4j.Logger;
7	import org.slf4j.LoggerFactory;
8	import org.springframework.stereotype.Service;
9	
10	/**
11	 * Orchestrates TX-A -> PG call -> TX-C. NOT transactional: the PG call must never run inside a DB
12	 * transaction (R11). All transactional work lives in PaymentTxService.
13	 */
14	@Service
15	public class PaymentService {
16	
17	    private static final Logger log = LoggerFactory.getLogger(PaymentService.class);
18	
19	    public record PayOutcome(OrderResponse order, boolean replayed) {
20	    }
21	
22	    private final PaymentTxService tx;
23	    private final PaymentGatewayClient gateway;
24	
25	    public PaymentService(PaymentTxService tx, PaymentGatewayClient gateway) {
26	        this.tx = tx;
27	        this.gateway = gateway;
28	    }
29	
30	    public PayOutcome pay(long orderId, String idempotencyKey, String cardToken) {
31	        String cardHash = Hashing.sha256Hex(cardToken); // the raw token is never stored or logged
32	        PaymentTxService.PayBegin begin = tx.beginPayment(orderId, idempotencyKey, cardHash);
33	        if (begin.replay()) {
34	            return new PayOutcome(begin.replayedOrder(), true);
35	        }
36	        GatewayResult result;
37	        try {
38	            result = gateway.charge(orderId, begin.amount(), cardToken, idempotencyKey);
39	        } catch (GatewayException e) {
40	            abort(orderId, begin.token(), e);
41	            throw e.toApiException(orderId);
42	        } catch (RuntimeException e) {
43	            abort(orderId, begin.token(), e);
44	            throw e;
45	        }
46	        return new PayOutcome(tx.completePayment(orderId, begin.token(), result), false);
47	    }
48	
49	    public OrderResponse refund(long orderId) {
50	        PaymentTxService.RefundBegin begin = tx.beginRefund(orderId);
51	        try {
52	            gateway.refund(begin.pgPaymentId(), "refund-" + orderId);
53	        } catch (GatewayException e) {
54	            abort(orderId, begin.token(), e);
55	            throw e.toApiException(orderId);
56	        } catch (RuntimeException e) {
57	            abort(orderId, begin.token(), e);
58	            throw e;
59	        }
60	        return tx.completeRefund(orderId, begin.token());
61	    }
62	
63	    private void abort(long orderId, UUID token, RuntimeException cause) {
64	        log.warn("PG call failed for order {}: {}", orderId, cause.getMessage());
65	        tx.abortLease(orderId, token, cause.getMessage());
66	    }
67	}
