1	package com.example.order.payment;
2	
3	import com.example.order.common.ApiException;
4	import com.example.order.common.Problems;
5	import com.example.order.common.Times;
6	import com.example.order.config.OrderPaymentProperties;
7	import com.example.order.order.OrderAction;
8	import com.example.order.order.OrderAssembler;
9	import com.example.order.order.OrderRepository;
10	import com.example.order.order.OrderResponse;
11	import com.example.order.order.OrderRow;
12	import com.example.order.order.OrderStateMachine;
13	import com.example.order.order.OrderStatus;
14	import com.example.order.order.OrderTransitionService;
15	import com.example.order.order.ReservationReleaser;
16	import java.time.Clock;
17	import java.time.Instant;
18	import java.util.UUID;
19	import org.slf4j.Logger;
20	import org.slf4j.LoggerFactory;
21	import org.springframework.stereotype.Service;
22	import org.springframework.transaction.annotation.Transactional;
23	
24	/**
25	 * The short DB transactions around a PG call (TX-A before, TX-C after). Deliberately a separate bean from
26	 * PaymentService so the @Transactional proxies apply and the PG call itself stays outside any transaction.
27	 */
28	@Service
29	public class PaymentTxService {
30	
31	    private static final Logger log = LoggerFactory.getLogger(PaymentTxService.class);
32	
33	    public record PayBegin(boolean replay, OrderResponse replayedOrder, UUID token, long amount) {
34	    }
35	
36	    public record RefundBegin(UUID token, String pgPaymentId) {
37	    }
38	
39	    private final OrderRepository orders;
40	    private final PaymentRepository payments;
41	    private final OrderAssembler assembler;
42	    private final OrderTransitionService transitions;
43	    private final ReservationReleaser releaser;
44	    private final OrderPaymentProperties props;
45	    private final Clock clock;
46	
47	    public PaymentTxService(OrderRepository orders, PaymentRepository payments, OrderAssembler assembler,
48	                            OrderTransitionService transitions, ReservationReleaser releaser,
49	                            OrderPaymentProperties props, Clock clock) {
50	        this.orders = orders;
51	        this.payments = payments;
52	        this.assembler = assembler;
53	        this.transitions = transitions;
54	        this.releaser = releaser;
55	        this.props = props;
56	        this.clock = clock;
57	    }
58	
59	    /** TX-A for pay: replay/conflict/state decision, lazy expiry, lease claim, payment row upsert. */
60	    @Transactional(noRollbackFor = ApiException.class) // keep the lazy expiry when answering order-expired
61	    public PayBegin beginPayment(long orderId, String idempotencyKey, String cardHash) {
62	        Instant now = Times.now(clock);
63	        OrderRow order = loadOrder(orderId);
64	        PaymentRow payment = payments.findByOrderId(orderId).orElse(null);
65	
66	        if (payment != null) {
67	            if (payment.idempotencyKey().equals(idempotencyKey)) {
68	                if (!payment.requestHash().equals(cardHash)) {
69	                    throw Problems.idempotencyKeyConflict(
70	                            "The Idempotency-Key was already used with a different cardToken");
71	                }
72	                if (payment.status().isFinalDecision()) {
73	                    return new PayBegin(true, assembler.assemble(order), null, 0);
74	                }
75	            } else {
76	                if (order.status() == OrderStatus.PENDING_PAYMENT) {
77	                    throw Problems.idempotencyKeyConflict(
78	                            "This order already has a payment attempt bound to a different Idempotency-Key");
79	                }
80	                throw OrderStateMachine.failureFor(order, OrderAction.PAY, now);
81	            }
82	        }
83	
84	        if (order.status() != OrderStatus.PENDING_PAYMENT) {
85	            throw OrderStateMachine.failureFor(order, OrderAction.PAY, now);
86	        }
87	        if (!order.expiresAt().isAfter(now)) {
88	            if (!order.leaseActive(now)) {
89	                transitions.expireIfDue(orderId);
90	            }
91	            throw OrderStateMachine.failureFor(loadOrder(orderId), OrderAction.PAY, now);
92	        }
93	
94	        UUID token = UUID.randomUUID();
95	        if (orders.claimPayLease(orderId, token, now, now.plus(props.leaseDuration())) != 1) {
96	            throw OrderStateMachine.failureFor(loadOrder(orderId), OrderAction.PAY, now);
97	        }
98	        payments.upsertInitiated(orderId, idempotencyKey, cardHash, order.totalPrice(), now);
99	        return new PayBegin(false, null, token, order.totalPrice());
100	    }
101	
102	    /** TX-C for pay: APPROVED -> PAID, DECLINED -> PAYMENT_FAILED (+ stock/coupon give-back). */
103	    @Transactional
104	    public OrderResponse completePayment(long orderId, UUID token, GatewayResult result) {
105	        Instant now = Times.now(clock);
106	        OrderStatus target = result.approved() ? OrderStatus.PAID : OrderStatus.PAYMENT_FAILED;
107	        if (orders.completePayment(orderId, target, token, now) != 1) {
108	            log.error("Payment completion lost the lease for order {} (PG result {}); manual reconciliation needed",
109	                    orderId, target);
110	            throw Problems.operationInProgress("PAY");
111	        }
112	        if (result.approved()) {
113	            payments.markApproved(orderId, result.paymentId(), now);
114	        } else {
115	            releaser.release(orderId, now);
116	            payments.markDeclined(orderId, now);
117	        }
118	        return assembler.load(orderId);
119	    }
120	
121	    /** TX-C for a gateway failure: only drop the lease, keep the order PENDING_PAYMENT / PAID. */
122	    @Transactional
123	    public void abortLease(long orderId, UUID token, String error) {
124	        Instant now = Times.now(clock);
125	        orders.releaseLease(orderId, token, now);
126	        payments.recordError(orderId, error, now);
127	    }
128	
129	    /** TX-A for refund (cancel on PAID). */
130	    @Transactional
131	    public RefundBegin beginRefund(long orderId) {
132	        Instant now = Times.now(clock);
133	        UUID token = UUID.randomUUID();
134	        if (orders.claimRefundLease(orderId, token, now, now.plus(props.leaseDuration())) != 1) {
135	            throw OrderStateMachine.failureFor(loadOrder(orderId), OrderAction.CANCEL, now);
136	        }
137	        PaymentRow payment = payments.findByOrderId(orderId)
138	                .orElseThrow(() -> new IllegalStateException("PAID order without payment row: " + orderId));
139	        if (payment.pgPaymentId() == null) {
140	            throw new IllegalStateException("PAID order without pg payment id: " + orderId);
141	        }
142	        return new RefundBegin(token, payment.pgPaymentId());
143	    }
144	
145	    /** TX-C for refund: PAID -> REFUNDED with stock/coupon give-back. */
146	    @Transactional
147	    public OrderResponse completeRefund(long orderId, UUID token) {
148	        Instant now = Times.now(clock);
149	        if (orders.completeRefund(orderId, token, now) != 1) {
150	            log.error("Refund completion lost the lease for order {}; manual reconciliation needed", orderId);
151	            throw Problems.operationInProgress("REFUND");
152	        }
153	        releaser.release(orderId, now);
154	        payments.markRefunded(orderId, now);
155	        return assembler.load(orderId);
156	    }
157	
158	    private OrderRow loadOrder(long orderId) {
159	        return orders.findById(orderId).orElseThrow(() -> Problems.orderNotFound(orderId));
160	    }
161	}
