1	package com.example.order.payment;
2	
3	import com.example.order.config.OrderPaymentProperties;
4	import com.fasterxml.jackson.databind.JsonNode;
5	import com.fasterxml.jackson.databind.ObjectMapper;
6	import java.io.IOException;
7	import java.net.SocketTimeoutException;
8	import java.net.http.HttpClient;
9	import java.net.http.HttpTimeoutException;
10	import java.util.LinkedHashMap;
11	import java.util.Map;
12	import org.springframework.http.MediaType;
13	import org.springframework.http.client.JdkClientHttpRequestFactory;
14	import org.springframework.stereotype.Component;
15	import org.springframework.web.client.RestClient;
16	import org.springframework.web.client.RestClientException;
17	
18	/**
19	 * External PG over HTTP. Never retries internally. Must be called outside any DB transaction.
20	 * Timeouts -> GatewayException(TIMEOUT); everything else abnormal -> GatewayException(ERROR).
21	 */
22	@Component
23	public class PaymentGatewayClient {
24	
25	    private final RestClient client;
26	    private final ObjectMapper objectMapper;
27	
28	    public PaymentGatewayClient(RestClient.Builder builder, ObjectMapper objectMapper, OrderPaymentProperties props) {
29	        HttpClient http = HttpClient.newBuilder()
30	                .version(HttpClient.Version.HTTP_1_1)
31	                .connectTimeout(props.gateway().connectTimeout())
32	                .build();
33	        JdkClientHttpRequestFactory factory = new JdkClientHttpRequestFactory(http);
34	        factory.setReadTimeout(props.gateway().readTimeout());
35	        this.client = builder.baseUrl(props.gateway().url()).requestFactory(factory).build();
36	        this.objectMapper = objectMapper;
37	    }
38	
39	    /** POST /v1/payments. */
40	    public GatewayResult charge(long orderId, long amount, String cardToken, String idempotencyKey) {
41	        Map<String, Object> body = new LinkedHashMap<>();
42	        body.put("orderId", orderId);
43	        body.put("amount", amount);
44	        body.put("cardToken", cardToken);
45	        JsonNode json = post(client.post().uri("/v1/payments").header("Idempotency-Key", idempotencyKey), body);
46	        String status = text(json, "status");
47	        String paymentId = text(json, "paymentId");
48	        if ("APPROVED".equals(status)) {
49	            if (paymentId == null || paymentId.isBlank() || paymentId.length() > 128) {
50	                throw new GatewayException(GatewayException.Kind.ERROR, "PG APPROVED without a usable paymentId", null);
51	            }
52	            return new GatewayResult(paymentId, true);
53	        }
54	        if ("DECLINED".equals(status)) {
55	            return new GatewayResult(paymentId, false);
56	        }
57	        throw new GatewayException(GatewayException.Kind.ERROR, "PG returned unexpected status", null);
58	    }
59	
60	    /** POST /v1/payments/{paymentId}/refund. */
61	    public GatewayResult refund(String paymentId, String idempotencyKey) {
62	        JsonNode json = post(client.post().uri("/v1/payments/{paymentId}/refund", paymentId)
63	                .header("Idempotency-Key", idempotencyKey), null);
64	        if (!"REFUNDED".equals(text(json, "status"))) {
65	            throw new GatewayException(GatewayException.Kind.ERROR, "PG returned unexpected refund status", null);
66	        }
67	        return new GatewayResult(paymentId, true);
68	    }
69	
70	    private JsonNode post(RestClient.RequestBodySpec spec, Object body) {
71	        try {
72	            RestClient.RequestBodySpec prepared = spec.contentType(MediaType.APPLICATION_JSON).accept(MediaType.APPLICATION_JSON);
73	            if (body != null) {
74	                prepared = prepared.body(body);
75	            }
76	            return prepared.exchange((request, response) -> {
77	                int code = response.getStatusCode().value();
78	                if (code < 200 || code >= 300) {
79	                    throw new GatewayException(GatewayException.Kind.ERROR, "PG responded with HTTP " + code, null);
80	                }
81	                try {
82	                    JsonNode node = objectMapper.readTree(response.getBody());
83	                    if (node == null || !node.isObject()) {
84	                        throw new GatewayException(GatewayException.Kind.ERROR, "PG response is not a JSON object", null);
85	                    }
86	                    return node;
87	                } catch (IOException e) {
88	                    throw classify(e);
89	                }
