98	    private static GatewayException classify(Throwable t) {
99	        for (Throwable c = t; c != null; c = c.getCause()) {
100	            if (c instanceof SocketTimeoutException || c instanceof HttpTimeoutException) {
101	                return new GatewayException(GatewayException.Kind.TIMEOUT, "PG call timed out", t);
