8	/** The single place that defines which status transitions exist (R15). */
9	public enum OrderStatus {
10	    PENDING_PAYMENT, PAID, PAYMENT_FAILED, EXPIRED, CANCELLED, REFUNDED, SHIPPED, DELIVERED;
11	
12	    private static final Map<OrderStatus, Set<OrderStatus>> ALLOWED = new EnumMap<>(OrderStatus.class);
13	
14	    static {
15	        ALLOWED.put(PENDING_PAYMENT, EnumSet.of(PAID, PAYMENT_FAILED, EXPIRED, CANCELLED));
16	        ALLOWED.put(PAID, EnumSet.of(SHIPPED, REFUNDED));
17	        ALLOWED.put(SHIPPED, EnumSet.of(DELIVERED));
18	        for (OrderStatus s : values()) {
19	            ALLOWED.putIfAbsent(s, EnumSet.noneOf(OrderStatus.class));
20	        }
21	    }
