23	    public boolean canTransitionTo(OrderStatus target) {
24	        return ALLOWED.get(this).contains(target);
25	    }
26	
27	    /** Guard used by every conditional-UPDATE method before issuing its SQL (programming-error check). */
28	    public static void requireTransition(OrderStatus from, OrderStatus to) {
29	        if (!from.canTransitionTo(to)) {
30	            throw new IllegalStateException("Illegal order transition " + from + " -> " + to);
31	        }
32	    }
