1	package com.example.order.config;
2	
3	import java.net.URI;
4	import java.time.Duration;
5	import org.springframework.boot.context.properties.ConfigurationProperties;
6	import org.springframework.boot.context.properties.bind.DefaultValue;
7	
8	/**
9	 * Bound from {@code order-payment.*}. Invalid values fail the binding, which makes application startup fail
10	 * (e.g. a malformed or non-positive ORDER_PAYMENT_TTL).
11	 */
12	@ConfigurationProperties(prefix = "order-payment")
13	public record OrderPaymentProperties(
14	        @DefaultValue("PT15M") Duration ttl,
15	        @DefaultValue("PT30S") Duration leaseDuration,
16	        @DefaultValue Gateway gateway,
17	        @DefaultValue Expiry expiry) {
18	
19	    public OrderPaymentProperties {
20	        requirePositive("order-payment.ttl", ttl);
21	        requirePositive("order-payment.lease-duration", leaseDuration);
22	        if (gateway == null || expiry == null) {
23	            throw new IllegalArgumentException("order-payment.gateway / order-payment.expiry must not be null");
24	        }
25	        Duration minLease = gateway.connectTimeout().plus(gateway.readTimeout()).multipliedBy(2);
26	        if (leaseDuration.compareTo(minLease) < 0) {
27	            throw new IllegalArgumentException(
28	                    "order-payment.lease-duration must be >= 2 x (connect-timeout + read-timeout) = " + minLease);
29	        }
30	    }
31	
32	    public record Gateway(
33	            @DefaultValue("http://localhost:8081") String url,
34	            @DefaultValue("PT2S") Duration connectTimeout,
35	            @DefaultValue("PT5S") Duration readTimeout) {
36	
37	        public Gateway {
38	            if (url == null || url.isBlank()) {
39	                throw new IllegalArgumentException("order-payment.gateway.url must not be blank");
40	            }
41	            try {
42	                URI uri = URI.create(url);
43	                String scheme = uri.getScheme();
44	                if (!uri.isAbsolute() || uri.getHost() == null
45	                        || !("http".equalsIgnoreCase(scheme) || "https".equalsIgnoreCase(scheme))) {
46	                    throw new IllegalArgumentException("not an absolute http(s) URI");
47	                }
48	            } catch (IllegalArgumentException e) {
49	                throw new IllegalArgumentException("order-payment.gateway.url is invalid: " + e.getMessage(), e);
50	            }
51	            requirePositive("order-payment.gateway.connect-timeout", connectTimeout);
52	            requirePositive("order-payment.gateway.read-timeout", readTimeout);
53	        }
54	    }
55	
56	    public record Expiry(
57	            @DefaultValue("true") boolean sweepEnabled,
58	            @DefaultValue("PT10S") Duration sweepInterval,
59	            @DefaultValue("100") int batchSize) {
60	
61	        public Expiry {
62	            requirePositive("order-payment.expiry.sweep-interval", sweepInterval);
63	            if (batchSize < 1 || batchSize > 1000) {
64	                throw new IllegalArgumentException("order-payment.expiry.batch-size must be within 1..1000");
65	            }
66	        }
67	    }
68	
69	    private static void requirePositive(String name, Duration d) {
70	        if (d == null || d.isZero() || d.isNegative()) {
71	            throw new IllegalArgumentException(name + " must be a positive ISO-8601 duration");
72	        }
73	    }
74	}
