1	package com.example.order.order;
2	
3	import com.example.order.common.Times;
4	import com.example.order.config.OrderPaymentProperties;
5	import java.time.Clock;
6	import java.util.List;
7	import org.slf4j.Logger;
8	import org.slf4j.LoggerFactory;
9	import org.springframework.stereotype.Component;
10	
11	/** Batch expiry. Each order is expired in its own transaction; overlapping runs/instances are harmless. */
12	@Component
13	public class OrderExpirySweeper {
14	
15	    private static final Logger log = LoggerFactory.getLogger(OrderExpirySweeper.class);
16	    private static final int MAX_BATCHES_PER_RUN = 10;
17	
18	    private final OrderRepository orders;
19	    private final OrderTransitionService transitions;
20	    private final OrderPaymentProperties props;
21	    private final Clock clock;
22	
23	    public OrderExpirySweeper(OrderRepository orders, OrderTransitionService transitions,
24	                              OrderPaymentProperties props, Clock clock) {
25	        this.orders = orders;
26	        this.transitions = transitions;
27	        this.props = props;
28	        this.clock = clock;
29	    }
30	
31	    /** @return number of orders this run actually expired */
32	    public int sweepOnce() {
33	        int expired = 0;
34	        for (int batch = 0; batch < MAX_BATCHES_PER_RUN; batch++) {
35	            List<Long> due = orders.findDueIds(Times.now(clock), null, props.expiry().batchSize());
36	            for (Long id : due) {
37	                try {
38	                    if (transitions.expireIfDue(id)) {
39	                        expired++;
40	                    }
41	                } catch (RuntimeException e) {
42	                    log.error("Expiry failed for order {}", id, e);
43	                }
44	            }
45	            if (due.size() < props.expiry().batchSize()) {
46	                break;
47	            }
48	        }
49	        return expired;
50	    }
51	}
