package com.example.order.support;

import com.fasterxml.jackson.databind.ObjectMapper;
import org.junit.jupiter.api.BeforeEach;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.boot.test.context.TestConfiguration;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Import;
import org.springframework.context.annotation.Primary;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.test.context.DynamicPropertyRegistry;
import org.springframework.test.context.DynamicPropertySource;
import org.springframework.test.web.servlet.MockMvc;
import org.testcontainers.containers.PostgreSQLContainer;

/**
 * Shared base: one PostgreSQL Testcontainer + one PG stub per JVM, full Spring context, MutableClock,
 * sweep scheduler disabled (tests call the sweeper explicitly). Tables are truncated before each test.
 */
@SpringBootTest(properties = {
        "order-payment.expiry.sweep-enabled=false",
        "order-payment.gateway.connect-timeout=PT1S",
        "order-payment.gateway.read-timeout=PT1S"
})
@AutoConfigureMockMvc
@Import(AbstractIntegrationTest.TestClockConfig.class)
public abstract class AbstractIntegrationTest {

    static final PostgreSQLContainer<?> POSTGRES = new PostgreSQLContainer<>("postgres:16-alpine");
    protected static final PaymentGatewayStub GATEWAY = new PaymentGatewayStub();

    static {
        POSTGRES.start();
        GATEWAY.start();
        Runtime.getRuntime().addShutdownHook(new Thread(GATEWAY::stop));
    }

    @DynamicPropertySource
    static void dynamicProperties(DynamicPropertyRegistry registry) {
        registry.add("spring.datasource.url", POSTGRES::getJdbcUrl);
        registry.add("spring.datasource.username", POSTGRES::getUsername);
        registry.add("spring.datasource.password", POSTGRES::getPassword);
        registry.add("order-payment.gateway.url", GATEWAY::baseUrl);
    }

    @TestConfiguration
    static class TestClockConfig {
        @Bean
        @Primary
        MutableClock testClock() {
            return new MutableClock();
        }
    }

    @Autowired
    protected MockMvc mvc;
    @Autowired
    protected MutableClock clock;
    @Autowired
    protected JdbcTemplate jdbc;
    @Autowired
    protected ObjectMapper objectMapper;

    protected ApiClient api;

    @BeforeEach
    void resetState() {
        jdbc.execute("TRUNCATE TABLE payments, order_items, orders, coupons, products RESTART IDENTITY CASCADE");
        GATEWAY.reset();
        clock.reset();
        api = new ApiClient(mvc, objectMapper);
    }

    protected int reserved(long productId) {
        return jdbc.queryForObject("SELECT reserved FROM products WHERE id = ?", Integer.class, productId);
    }

    protected int stock(long productId) {
        return jdbc.queryForObject("SELECT stock FROM products WHERE id = ?", Integer.class, productId);
    }

    protected int couponUsed(String code) {
        return jdbc.queryForObject("SELECT used_count FROM coupons WHERE code = ?", Integer.class, code);
    }
}
package com.example.order.support;

import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.node.ArrayNode;
import com.fasterxml.jackson.databind.node.ObjectNode;
import java.time.Duration;
import java.time.Instant;
import org.springframework.http.MediaType;
import org.springframework.test.web.servlet.MockMvc;
import org.springframework.test.web.servlet.MvcResult;
import org.springframework.test.web.servlet.ResultActions;

/** Thin helper over MockMvc so test bodies read as API scenarios. */
public class ApiClient {

    private final MockMvc mvc;
    private final ObjectMapper om;

    public ApiClient(MockMvc mvc, ObjectMapper om) {
        this.mvc = mvc;
        this.om = om;
    }

    public ObjectMapper objectMapper() {
        return om;
    }

    // ---------- products / coupons ----------

    public ResultActions postProduct(Object body) throws Exception {
        return mvc.perform(post("/api/products").contentType(MediaType.APPLICATION_JSON).content(om.writeValueAsString(body)));
    }

    public long createProduct(String name, long price, int stock) throws Exception {
        ObjectNode body = om.createObjectNode().put("name", name).put("price", price).put("stock", stock);
        return json(postProduct(body).andReturn()).get("id").asLong();
    }

    public ObjectNode couponBody(String code, String type, long value, Long minOrder, Long maxDiscount, int total,
                                 Instant from, Instant until) {
        ObjectNode body = om.createObjectNode().put("code", code).put("type", type).put("value", value)
                .put("totalQuantity", total).put("validFrom", from.toString()).put("validUntil", until.toString());
        if (minOrder != null) {
            body.put("minOrderAmount", minOrder);
        }
        if (maxDiscount != null) {
            body.put("maxDiscountAmount", maxDiscount);
        }
        return body;
    }

    public ResultActions postCoupon(Object body) throws Exception {
        return mvc.perform(post("/api/coupons").contentType(MediaType.APPLICATION_JSON).content(om.writeValueAsString(body)));
    }

    /** Coupon valid from one hour ago to one day ahead (relative to real time; tests use a real-time-anchored clock). */
    public void createCoupon(String code, String type, long value, Long minOrder, Long maxDiscount, int total) throws Exception {
        Instant now = Instant.now();
        postCoupon(couponBody(code, type, value, minOrder, maxDiscount, total, now.minus(Duration.ofHours(1)),
                now.plus(Duration.ofDays(1)))).andReturn();
    }

    // ---------- orders ----------

    public ObjectNode orderBody(String couponCode, long... productIdAndQuantityPairs) {
        ObjectNode body = om.createObjectNode();
        ArrayNode items = body.putArray("items");
        for (int i = 0; i < productIdAndQuantityPairs.length; i += 2) {
            items.addObject().put("productId", productIdAndQuantityPairs[i]).put("quantity", (int) productIdAndQuantityPairs[i + 1]);
        }
        if (couponCode != null) {
            body.put("couponCode", couponCode);
        }
        return body;
    }

    public ResultActions postOrder(String userId, String key, Object body) throws Exception {
        var req = post("/api/orders").contentType(MediaType.APPLICATION_JSON).content(om.writeValueAsString(body));
        if (userId != null) {
            req.header("X-User-Id", userId);
        }
        if (key != null) {
            req.header("Idempotency-Key", key);
        }
        return mvc.perform(req);
    }

    /** Creates an order that is expected to succeed (201) and returns its JSON. */
    public JsonNode createOrder(String userId, String key, String couponCode, long... productIdAndQuantityPairs) throws Exception {
        MvcResult result = postOrder(userId, key, orderBody(couponCode, productIdAndQuantityPairs)).andReturn();
        if (result.getResponse().getStatus() != 201) {
            throw new AssertionError("expected 201 but got " + result.getResponse().getStatus() + ": "
                    + result.getResponse().getContentAsString());
        }
        return json(result);
    }

    public void getProductAvailable(long productId, int expectedAvailable) throws Exception {
        mvc.perform(get("/api/products/" + productId))
                .andExpect(org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath("$.available").value(expectedAvailable));
    }

    public ResultActions getOrder(long id) throws Exception {
        return mvc.perform(get("/api/orders/" + id));
    }

    public ResultActions listOrders(String query) throws Exception {
        return mvc.perform(get("/api/orders" + (query == null || query.isEmpty() ? "" : "?" + query)));
    }

    public ResultActions pay(long orderId, String key, String cardToken) throws Exception {
        var req = post("/api/orders/" + orderId + "/pay").contentType(MediaType.APPLICATION_JSON)
                .content(om.writeValueAsString(om.createObjectNode().put("cardToken", cardToken)));
        if (key != null) {
            req.header("Idempotency-Key", key);
        }
        return mvc.perform(req);
    }

    public ResultActions action(long orderId, String action) throws Exception {
        return mvc.perform(post("/api/orders/" + orderId + "/" + action));
    }

    /** Create order then pay it successfully; returns the order id. */
    public long createPaidOrder(String userId, String key, String couponCode, long... pairs) throws Exception {
        long id = createOrder(userId, key, couponCode, pairs).get("id").asLong();
        MvcResult paid = pay(id, "pay-" + key, "tok_test").andReturn();
        if (paid.getResponse().getStatus() != 200) {
            throw new AssertionError("pay failed: " + paid.getResponse().getContentAsString());
        }
        return id;
    }

    public JsonNode json(MvcResult result) throws Exception {
        return om.readTree(result.getResponse().getContentAsString());
    }
}
package com.example.order.support;

import java.time.Clock;
import java.time.Duration;
import java.time.Instant;
import java.time.ZoneId;
import java.time.ZoneOffset;

/** Test clock that can be advanced to exercise TTL/validity logic without sleeping. */
public class MutableClock extends Clock {

    private volatile Instant now = Instant.now();

    @Override
    public ZoneId getZone() {
        return ZoneOffset.UTC;
    }

    @Override
    public Clock withZone(ZoneId zone) {
        return this;
    }

    @Override
    public Instant instant() {
        return now;
    }

    public void reset() {
        now = Instant.now();
    }

    public void set(Instant instant) {
        now = instant;
    }

    public void advance(Duration duration) {
        now = now.plus(duration);
    }
}
package com.example.order.support;

import com.sun.net.httpserver.HttpExchange;
import com.sun.net.httpserver.HttpServer;
import java.io.IOException;
import java.io.OutputStream;
import java.net.InetAddress;
import java.net.InetSocketAddress;
import java.nio.charset.StandardCharsets;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.CopyOnWriteArrayList;
import java.util.concurrent.Executors;
import java.util.concurrent.atomic.AtomicLong;
import java.util.stream.Collectors;

/**
 * In-process fake of the external PG (JDK HttpServer, no extra dependency). Honors Idempotency-Key on charges:
 * the same key returns the same payment instead of creating a new one.
 */
public class PaymentGatewayStub {

    public enum Behavior { OK, DECLINE, SERVER_ERROR, MALFORMED }

    public record RecordedRequest(String method, String path, Map<String, String> headers, String body) {
    }

    private final List<RecordedRequest> requests = new CopyOnWriteArrayList<>();
    private final Map<String, String> chargeResponsesByKey = new ConcurrentHashMap<>();
    private final AtomicLong sequence = new AtomicLong();
    private volatile Behavior chargeBehavior = Behavior.OK;
    private volatile Behavior refundBehavior = Behavior.OK;
    private volatile long delayMillis = 0;
    private HttpServer server;

    public void start() {
        try {
            server = HttpServer.create(new InetSocketAddress(InetAddress.getLoopbackAddress(), 0), 0);
            server.createContext("/", this::handle);
            server.setExecutor(Executors.newCachedThreadPool());
            server.start();
        } catch (IOException e) {
            throw new IllegalStateException(e);
        }
    }

    public void stop() {
        if (server != null) {
            server.stop(0);
        }
    }

    public String baseUrl() {
        return "http://127.0.0.1:" + server.getAddress().getPort();
    }

    public void reset() {
        requests.clear();
        chargeResponsesByKey.clear();
        chargeBehavior = Behavior.OK;
        refundBehavior = Behavior.OK;
        delayMillis = 0;
    }

    public void chargeBehavior(Behavior behavior) {
        this.chargeBehavior = behavior;
    }

    public void refundBehavior(Behavior behavior) {
        this.refundBehavior = behavior;
    }

    public void delayMillis(long millis) {
        this.delayMillis = millis;
    }

    public List<RecordedRequest> requests() {
        return List.copyOf(requests);
    }

    public List<RecordedRequest> charges() {
        return requests.stream().filter(r -> r.path().equals("/v1/payments")).collect(Collectors.toList());
    }

    public List<RecordedRequest> refunds() {
        return requests.stream().filter(r -> r.path().endsWith("/refund")).collect(Collectors.toList());
    }

    private void handle(HttpExchange ex) throws IOException {
        String body = new String(ex.getRequestBody().readAllBytes(), StandardCharsets.UTF_8);
        Map<String, String> headers = ex.getRequestHeaders().entrySet().stream()
                .collect(Collectors.toMap(e -> e.getKey().toLowerCase(Locale.ROOT), e -> e.getValue().get(0), (a, b) -> a));
        String path = ex.getRequestURI().getPath();
        requests.add(new RecordedRequest(ex.getRequestMethod(), path, headers, body));
        try {
            if (delayMillis > 0) {
                Thread.sleep(delayMillis);
            }
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
        if (path.equals("/v1/payments") && "POST".equals(ex.getRequestMethod())) {
            respondCharge(ex, headers.getOrDefault("idempotency-key", ""));
        } else if (path.matches("/v1/payments/[^/]+/refund") && "POST".equals(ex.getRequestMethod())) {
            String paymentId = path.split("/")[3];
            respondRefund(ex, paymentId);
        } else {
            send(ex, 404, "{}");
        }
    }

    private void respondCharge(HttpExchange ex, String key) throws IOException {
        switch (chargeBehavior) {
            case SERVER_ERROR -> send(ex, 500, "{\"error\":\"boom\"}");
            case MALFORMED -> send(ex, 200, "not-json");
            default -> {
                String json = chargeResponsesByKey.computeIfAbsent(key, k -> {
                    String status = chargeBehavior == Behavior.DECLINE ? "DECLINED" : "APPROVED";
                    return "{\"paymentId\":\"pg-" + sequence.incrementAndGet() + "\",\"status\":\"" + status + "\"}";
                });
                send(ex, 200, json);
            }
        }
    }

    private void respondRefund(HttpExchange ex, String paymentId) throws IOException {
        if (refundBehavior == Behavior.SERVER_ERROR) {
            send(ex, 503, "{\"error\":\"unavailable\"}");
        } else {
            send(ex, 200, "{\"paymentId\":\"" + paymentId + "\",\"status\":\"REFUNDED\"}");
        }
    }

    private static void send(HttpExchange ex, int status, String json) throws IOException {
        byte[] bytes = json.getBytes(StandardCharsets.UTF_8);
        ex.getResponseHeaders().add("Content-Type", "application/json");
        ex.sendResponseHeaders(status, bytes.length);
        try (OutputStream os = ex.getResponseBody()) {
            os.write(bytes);
        }
    }
}

package com.example.order;

import static org.assertj.core.api.Assertions.assertThat;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

import com.example.order.support.AbstractIntegrationTest;
import com.example.order.support.PaymentGatewayStub.Behavior;
import org.junit.jupiter.api.Test;

class CancelRefundShipSmokeTest extends AbstractIntegrationTest {

    @Test
    void cancel_pendingOrder_releasesStockAndCouponWithoutCallingGateway() throws Exception {
        long product = api.createProduct("Desk", 1000, 5);
        api.createCoupon("C1", "FIXED", 100, null, null, 2);
        long orderId = api.createOrder("u", "k1", "C1", product, 2).get("id").asLong();

        api.action(orderId, "cancel")
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.status").value("CANCELLED"));

        assertThat(reserved(product)).isZero();
        assertThat(couponUsed("C1")).isZero();
        assertThat(GATEWAY.requests()).isEmpty();

        api.action(orderId, "cancel")
                .andExpect(status().isConflict())
                .andExpect(jsonPath("$.type").value("urn:problem:order-payment:invalid-order-state"));
        assertThat(reserved(product)).isZero(); // no double release
    }

    @Test
    void cancel_paidOrder_refundsViaGatewayAndReleasesOnce() throws Exception {
        long product = api.createProduct("Desk", 1000, 5);
        long orderId = api.createPaidOrder("u", "k1", null, product, 2);

        api.action(orderId, "cancel")
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.status").value("REFUNDED"));

        assertThat(GATEWAY.refunds()).hasSize(1);
        assertThat(GATEWAY.refunds().get(0).path()).matches("/v1/payments/pg-\\d+/refund");
        assertThat(reserved(product)).isZero();

        api.action(orderId, "cancel").andExpect(status().isConflict());
        assertThat(GATEWAY.refunds()).hasSize(1); // no double refund
    }

    @Test
    void cancel_paidOrder_gatewayFailure_returns502KeepsPaidAndRetryRefunds() throws Exception {
        long product = api.createProduct("Desk", 1000, 5);
        long orderId = api.createPaidOrder("u", "k1", null, product, 2);
        GATEWAY.refundBehavior(Behavior.SERVER_ERROR);

        api.action(orderId, "cancel")
                .andExpect(status().isBadGateway())
                .andExpect(jsonPath("$.type").value("urn:problem:order-payment:pg-gateway-error"));
        api.getOrder(orderId).andExpect(jsonPath("$.status").value("PAID"));
        assertThat(reserved(product)).isEqualTo(2);

        GATEWAY.refundBehavior(Behavior.OK);
        api.action(orderId, "cancel")
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.status").value("REFUNDED"));
        assertThat(reserved(product)).isZero();
    }

    @Test
    void shipThenDeliver_confirmsStockAndAdvancesStatus() throws Exception {
        long product = api.createProduct("Desk", 1000, 5);
        long orderId = api.createPaidOrder("u", "k1", null, product, 2);

        api.action(orderId, "deliver")
                .andExpect(status().isConflict())
                .andExpect(jsonPath("$.type").value("urn:problem:order-payment:invalid-order-state"))
                .andExpect(jsonPath("$.action").value("deliver"));

        api.action(orderId, "ship")
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.status").value("SHIPPED"));
        assertThat(stock(product)).isEqualTo(3);
        assertThat(reserved(product)).isZero();
        api.getProductAvailable(product, 3);

        api.action(orderId, "ship").andExpect(status().isConflict());
        api.action(orderId, "cancel")
                .andExpect(status().isConflict())
                .andExpect(jsonPath("$.type").value("urn:problem:order-payment:invalid-order-state"));

        api.action(orderId, "deliver")
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.status").value("DELIVERED"));
        api.action(orderId, "deliver").andExpect(status().isConflict());
    }

    @Test
    void ship_pendingOrderOrUnknownOrder_returns409Or404() throws Exception {
        long product = api.createProduct("Desk", 1000, 5);
        long orderId = api.createOrder("u", "k1", null, product, 1).get("id").asLong();
        api.action(orderId, "ship").andExpect(status().isConflict());
        api.action(123456, "ship")
                .andExpect(status().isNotFound())
                .andExpect(jsonPath("$.type").value("urn:problem:order-payment:order-not-found"));
        api.action(123456, "cancel").andExpect(status().isNotFound());
    }
}
package com.example.order;

import static org.assertj.core.api.Assertions.assertThat;

import com.example.order.config.OrderPaymentProperties;
import java.time.Duration;
import org.junit.jupiter.api.Test;
import org.springframework.boot.context.properties.EnableConfigurationProperties;
import org.springframework.boot.test.context.runner.ApplicationContextRunner;
import org.springframework.context.annotation.Configuration;

/** No database needed: only exercises @ConfigurationProperties binding/validation. */
class ConfigurationPropertiesTest {

    @Configuration
    @EnableConfigurationProperties(OrderPaymentProperties.class)
    static class PropsConfig {
    }

    private final ApplicationContextRunner runner = new ApplicationContextRunner().withUserConfiguration(PropsConfig.class);

    @Test
    void defaults_areApplied() {
        runner.run(ctx -> {
            assertThat(ctx).hasNotFailed();
            OrderPaymentProperties p = ctx.getBean(OrderPaymentProperties.class);
            assertThat(p.ttl()).isEqualTo(Duration.ofMinutes(15));
            assertThat(p.gateway().url()).isEqualTo("http://localhost:8081");
            assertThat(p.gateway().connectTimeout()).isEqualTo(Duration.ofSeconds(2));
            assertThat(p.gateway().readTimeout()).isEqualTo(Duration.ofSeconds(5));
            assertThat(p.expiry().sweepEnabled()).isTrue();
        });
    }

    @Test
    void validIsoTtl_isBound() {
        runner.withPropertyValues("order-payment.ttl=PT30M")
                .run(ctx -> assertThat(ctx.getBean(OrderPaymentProperties.class).ttl()).isEqualTo(Duration.ofMinutes(30)));
    }

    @Test
    void malformedTtl_failsStartup() {
        runner.withPropertyValues("order-payment.ttl=15 minutes").run(ctx -> assertThat(ctx).hasFailed());
    }

    @Test
    void zeroOrNegativeTtl_failsStartup() {
        runner.withPropertyValues("order-payment.ttl=PT0S").run(ctx -> assertThat(ctx).hasFailed());
        runner.withPropertyValues("order-payment.ttl=-PT5M").run(ctx -> assertThat(ctx).hasFailed());
    }

    @Test
    void invalidGatewayUrlOrShortLease_failsStartup() {
        runner.withPropertyValues("order-payment.gateway.url=not a url").run(ctx -> assertThat(ctx).hasFailed());
        runner.withPropertyValues("order-payment.lease-duration=PT5S").run(ctx -> assertThat(ctx).hasFailed());
    }
}
