import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;

class OrderExpirySmokeTest extends AbstractIntegrationTest {

    @Autowired
    OrderExpirySweeper sweeper;

    @Test
    void getOrder_afterTtl_showsExpiredAndReleasesStockAndCouponExactlyOnce() throws Exception {
        long product = api.createProduct("Desk", 1000, 5);
        api.createCoupon("C1", "FIXED", 100, null, null, 2);
        long orderId = api.createOrder("u", "k1", "C1", product, 2).get("id").asLong();

        clock.advance(Duration.ofMinutes(14));
        api.getOrder(orderId).andExpect(jsonPath("$.status").value("PENDING_PAYMENT"));
        assertThat(reserved(product)).isEqualTo(2);

        clock.advance(Duration.ofMinutes(2));
        api.getOrder(orderId).andExpect(jsonPath("$.status").value("EXPIRED"));
        api.getOrder(orderId).andExpect(jsonPath("$.status").value("EXPIRED"));

        assertThat(reserved(product)).isZero();
        assertThat(couponUsed("C1")).isZero();
    }

    @Test
    void payAndCancel_onExpiredOrder_return409OrderExpired() throws Exception {
        long product = api.createProduct("Desk", 1000, 5);
        long orderId = api.createOrder("u", "k1", null, product, 2).get("id").asLong();
        clock.advance(Duration.ofMinutes(16));

        api.pay(orderId, "pay-1", "tok")
                .andExpect(status().isConflict())
                .andExpect(jsonPath("$.type").value("urn:problem:order-payment:order-expired"))
                .andExpect(jsonPath("$.expiresAt").exists());
        assertThat(GATEWAY.requests()).isEmpty();
        assertThat(reserved(product)).isZero(); // the lazy expiry inside pay was committed

        api.action(orderId, "cancel")
                .andExpect(status().isConflict())
                .andExpect(jsonPath("$.type").value("urn:problem:order-payment:order-expired"));
        assertThat(reserved(product)).isZero();
    }

    @Test
    void sweeper_expiresDueOrdersOnlyAndIsIdempotent() throws Exception {
        long product = api.createProduct("Desk", 1000, 10);
        long due = api.createOrder("u", "k1", null, product, 2).get("id").asLong();
        clock.advance(Duration.ofMinutes(10));
        long notDue = api.createOrder("u", "k2", null, product, 3).get("id").asLong();
        clock.advance(Duration.ofMinutes(6)); // first order is 16 min old, second 6 min

        assertThat(sweeper.sweepOnce()).isEqualTo(1);
        assertThat(sweeper.sweepOnce()).isZero();

        assertThat(jdbc.queryForObject("SELECT status FROM orders WHERE id = ?", String.class, due)).isEqualTo("EXPIRED");
        assertThat(jdbc.queryForObject("SELECT status FROM orders WHERE id = ?", String.class, notDue)).isEqualTo("PENDING_PAYMENT");
        assertThat(reserved(product)).isEqualTo(3);
    }

    @Test
    void paidOrder_isNotExpiredByTtl() throws Exception {
        long product = api.createProduct("Desk", 1000, 5);
        long orderId = api.createPaidOrder("u", "k1", null, product, 1);
        clock.advance(Duration.ofHours(1));
        assertThat(sweeper.sweepOnce()).isZero();
        api.getOrder(orderId).andExpect(jsonPath("$.status").value("PAID"));
    }
}

package com.example.order;

import static org.assertj.core.api.Assertions.assertThat;
import static org.hamcrest.Matchers.hasSize;
import static org.hamcrest.Matchers.nullValue;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

import com.example.order.support.AbstractIntegrationTest;
import com.fasterxml.jackson.databind.JsonNode;
import java.util.ArrayList;
import java.util.List;
import org.junit.jupiter.api.Test;

class OrderListCursorSmokeTest extends AbstractIntegrationTest {

    @Test
    void list_pagesByIdDescendingWithCursorAndEndsWithNullCursor() throws Exception {
        long product = api.createProduct("Desk", 100, 100);
        List<Long> ids = new ArrayList<>();
        for (int i = 1; i <= 5; i++) {
            ids.add(api.createOrder("u1", "k" + i, null, product, 1).get("id").asLong());
        }
        api.createOrder("u2", "k1", null, product, 1);

        JsonNode page1 = api.json(api.listOrders("userId=u1&size=2")
                .andExpect(status().isOk()).andExpect(jsonPath("$.content", hasSize(2))).andReturn());
        assertThat(page1.get("content").get(0).get("id").asLong()).isEqualTo(ids.get(4));
        assertThat(page1.get("content").get(1).get("id").asLong()).isEqualTo(ids.get(3));
        String cursor1 = page1.get("nextCursor").asText();

        JsonNode page2 = api.json(api.listOrders("userId=u1&size=2&cursor=" + cursor1).andReturn());
        assertThat(page2.get("content").get(0).get("id").asLong()).isEqualTo(ids.get(2));
        assertThat(page2.get("content").get(1).get("id").asLong()).isEqualTo(ids.get(1));

        JsonNode page3 = api.json(api.listOrders("userId=u1&size=2&cursor=" + page2.get("nextCursor").asText()).andReturn());
        assertThat(page3.get("content")).hasSize(1);
        assertThat(page3.get("content").get(0).get("id").asLong()).isEqualTo(ids.get(0));
        assertThat(page3.get("nextCursor").isNull()).isTrue();
    }

    @Test
    void list_filtersByStatus_andEmptyResultIsEmptyArray() throws Exception {
        long product = api.createProduct("Desk", 100, 100);
        long paid = api.createPaidOrder("u1", "k1", null, product, 1);
        api.createOrder("u1", "k2", null, product, 1);

        api.listOrders("userId=u1&status=PAID")
                .andExpect(jsonPath("$.content", hasSize(1)))
                .andExpect(jsonPath("$.content[0].id").value(paid))
                .andExpect(jsonPath("$.nextCursor").value(nullValue()));
        api.listOrders("userId=nobody")
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.content", hasSize(0)))
                .andExpect(jsonPath("$.nextCursor").value(nullValue()));
        api.listOrders("").andExpect(jsonPath("$.content", hasSize(2)));
    }

    @Test
    void list_invalidParameters_return400() throws Exception {
        api.listOrders("size=0").andExpect(status().isBadRequest())
                .andExpect(jsonPath("$.type").value("urn:problem:order-payment:validation-failed"));
        api.listOrders("size=101").andExpect(status().isBadRequest());
        api.listOrders("size=abc").andExpect(status().isBadRequest());
        api.listOrders("status=BOGUS").andExpect(status().isBadRequest())
                .andExpect(jsonPath("$.type").value("urn:problem:order-payment:validation-failed"));
        api.listOrders("cursor=not-a-cursor!").andExpect(status().isBadRequest())
                .andExpect(jsonPath("$.type").value("urn:problem:order-payment:invalid-cursor"));
        api.listOrders("cursor=" + java.util.Base64.getUrlEncoder().withoutPadding().encodeToString("v2:5".getBytes()))
                .andExpect(status().isBadRequest())
                .andExpect(jsonPath("$.type").value("urn:problem:order-payment:invalid-cursor"));
    }

    @Test
    void list_showsLazilyExpiredOrdersAsExpired() throws Exception {
        long product = api.createProduct("Desk", 100, 100);
        api.createOrder("u1", "k1", null, product, 1);
        clock.advance(java.time.Duration.ofMinutes(16));

        api.listOrders("userId=u1")
                .andExpect(jsonPath("$.content[0].status").value("EXPIRED"));
        assertThat(reserved(product)).isZero();
    }

    @Test
    void list_statusExpired_includesOrdersPastTtlBeforeSchedulerRuns() throws Exception {
        long product = api.createProduct("Desk", 100, 100);
        api.createCoupon("C1", "FIXED", 10, null, null, 2);
        long orderId = api.createOrder("u1", "k1", "C1", product, 2).get("id").asLong();
        clock.advance(java.time.Duration.ofMinutes(16));

        api.listOrders("status=EXPIRED")
                .andExpect(jsonPath("$.content", hasSize(1)))
                .andExpect(jsonPath("$.content[0].id").value(orderId));
        api.listOrders("status=EXPIRED").andExpect(jsonPath("$.content", hasSize(1)));
        assertThat(reserved(product)).isZero();
        assertThat(couponUsed("C1")).isZero();
    }
}
package com.example.order;

import static org.assertj.core.api.Assertions.assertThat;
import static org.hamcrest.Matchers.nullValue;
import static org.hamcrest.Matchers.notNullValue;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.header;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

import com.example.order.support.AbstractIntegrationTest;
import com.example.order.support.PaymentGatewayStub.Behavior;
import com.fasterxml.jackson.databind.JsonNode;
import org.junit.jupiter.api.Test;

class PaymentSmokeTest extends AbstractIntegrationTest {

    private long productId;

    private long newPendingOrder(String key) throws Exception {
        if (productId == 0) {
            productId = api.createProduct("Laptop", 20000, 10);
        }
        return api.createOrder("user-1", key, null, productId, 2).get("id").asLong();
    }

    @Test
    void pay_approved_marksPaidAndSendsExpectedGatewayRequest() throws Exception {
        long orderId = newPendingOrder("o1");

        api.pay(orderId, "pay-1", "tok_visa")
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.status").value("PAID"))
                .andExpect(jsonPath("$.paidAt").value(notNullValue()));

        assertThat(GATEWAY.charges()).hasSize(1);
        var call = GATEWAY.charges().get(0);
        assertThat(call.headers().get("idempotency-key")).isEqualTo("pay-1");
        JsonNode body = objectMapper.readTree(call.body());
        assertThat(body.get("orderId").asLong()).isEqualTo(orderId);
        assertThat(body.get("amount").asLong()).isEqualTo(40000);
        assertThat(body.get("cardToken").asText()).isEqualTo("tok_visa");
        assertThat(reserved(productId)).isEqualTo(2); // reservation kept until ship
        assertThat(jdbc.queryForObject("SELECT pg_payment_id FROM payments WHERE order_id = ?", String.class, orderId))
                .startsWith("pg-");
        assertThat(jdbc.queryForObject("SELECT request_hash FROM payments WHERE order_id = ?", String.class, orderId))
                .hasSize(64).isNotEqualTo("tok_visa"); // only a SHA-256 of the card token is stored
    }

    @Test
    void pay_sameKeyAgain_replaysWithoutCallingGatewayAgain() throws Exception {
        long orderId = newPendingOrder("o1");
        api.pay(orderId, "pay-1", "tok_visa").andExpect(status().isOk());

        api.pay(orderId, "pay-1", "tok_visa")
                .andExpect(status().isOk())
                .andExpect(header().string("Idempotent-Replayed", "true"))
                .andExpect(jsonPath("$.status").value("PAID"));
        assertThat(GATEWAY.charges()).hasSize(1);

        api.pay(orderId, "pay-1", "tok_other")
                .andExpect(status().isConflict())
                .andExpect(jsonPath("$.type").value("urn:problem:order-payment:idempotency-key-conflict"));
    }

    @Test
    void pay_declined_marksPaymentFailedAndReleasesStockAndCoupon() throws Exception {
        long product = api.createProduct("Laptop", 20000, 10);
        api.createCoupon("C1", "FIXED", 1000, null, null, 3);
        long orderId = api.createOrder("user-1", "o1", "C1", product, 2).get("id").asLong();
        assertThat(reserved(product)).isEqualTo(2);
        assertThat(couponUsed("C1")).isEqualTo(1);

        GATEWAY.chargeBehavior(Behavior.DECLINE);
        api.pay(orderId, "pay-1", "tok_bad")
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.status").value("PAYMENT_FAILED"))
                .andExpect(jsonPath("$.paidAt").value(nullValue()));

        assertThat(reserved(product)).isZero();
        assertThat(couponUsed("C1")).isZero();
        api.pay(orderId, "pay-2", "tok_visa")
                .andExpect(status().isConflict())
                .andExpect(jsonPath("$.type").value("urn:problem:order-payment:invalid-order-state"))
                .andExpect(jsonPath("$.currentStatus").value("PAYMENT_FAILED"));
    }

    @Test
    void pay_gatewayServerError_returns502KeepsPendingAndSameKeyRetrySucceeds() throws Exception {
        long orderId = newPendingOrder("o1");
        GATEWAY.chargeBehavior(Behavior.SERVER_ERROR);

        api.pay(orderId, "pay-1", "tok_visa")
                .andExpect(status().isBadGateway())
                .andExpect(jsonPath("$.type").value("urn:problem:order-payment:pg-gateway-error"))
                .andExpect(jsonPath("$.retryable").value(true));
        api.getOrder(orderId).andExpect(jsonPath("$.status").value("PENDING_PAYMENT"));
        assertThat(jdbc.queryForObject("SELECT lease_token IS NULL FROM orders WHERE id = ?", Boolean.class, orderId)).isTrue();

        // a different key is refused: the order is bound to the first payment key
        api.pay(orderId, "pay-2", "tok_visa")
                .andExpect(status().isConflict())
                .andExpect(jsonPath("$.type").value("urn:problem:order-payment:idempotency-key-conflict"));

        GATEWAY.chargeBehavior(Behavior.OK);
        api.pay(orderId, "pay-1", "tok_visa")
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.status").value("PAID"));
    }

    @Test
    void pay_malformedGatewayResponse_returns502() throws Exception {
        long orderId = newPendingOrder("o1");
        GATEWAY.chargeBehavior(Behavior.MALFORMED);
        api.pay(orderId, "pay-1", "tok_visa")
                .andExpect(status().isBadGateway());
        api.getOrder(orderId).andExpect(jsonPath("$.status").value("PENDING_PAYMENT"));
    }

    @Test
    void pay_gatewayTimeout_returns504AndKeepsPending() throws Exception {
        long orderId = newPendingOrder("o1");
        GATEWAY.delayMillis(2500); // read-timeout is PT1S in tests

        api.pay(orderId, "pay-1", "tok_visa")
                .andExpect(status().isGatewayTimeout())
                .andExpect(jsonPath("$.type").value("urn:problem:order-payment:pg-gateway-timeout"));
        api.getOrder(orderId).andExpect(jsonPath("$.status").value("PENDING_PAYMENT"));
    }

    @Test
    void pay_inputErrors_return400And404() throws Exception {
        long orderId = newPendingOrder("o1");
        api.pay(orderId, null, "tok")
                .andExpect(status().isBadRequest())
                .andExpect(jsonPath("$.type").value("urn:problem:order-payment:missing-header"));
        api.pay(orderId, "k", "  ")
                .andExpect(status().isBadRequest())
                .andExpect(jsonPath("$.type").value("urn:problem:order-payment:validation-failed"));
        api.pay(987654, "k", "tok")
                .andExpect(status().isNotFound())
                .andExpect(jsonPath("$.type").value("urn:problem:order-payment:order-not-found"));
        assertThat(GATEWAY.requests()).isEmpty();
    }
}
package com.example.order;

import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.delete;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.content;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

import com.example.order.support.AbstractIntegrationTest;
import org.junit.jupiter.api.Test;
import org.springframework.http.MediaType;

class ProblemFormatSmokeTest extends AbstractIntegrationTest {

    private static final String PROBLEM = "application/problem+json";

    @Test
    void notFoundProblem_hasAllRfc9457Members() throws Exception {
        mvc.perform(get("/api/orders/777"))
                .andExpect(status().isNotFound())
                .andExpect(content().contentTypeCompatibleWith(PROBLEM))
                .andExpect(jsonPath("$.type").value("urn:problem:order-payment:order-not-found"))
                .andExpect(jsonPath("$.title").value("Order not found"))
                .andExpect(jsonPath("$.status").value(404))
                .andExpect(jsonPath("$.detail").isString())
                .andExpect(jsonPath("$.instance").value("/api/orders/777"));
    }

    @Test
    void unknownPath_returns404ProblemJson() throws Exception {
        mvc.perform(get("/api/nothing-here"))
                .andExpect(status().isNotFound())
                .andExpect(content().contentTypeCompatibleWith(PROBLEM))
                .andExpect(jsonPath("$.type").value("urn:problem:order-payment:resource-not-found"));
    }

    @Test
    void wrongMethod_returns405ProblemJson() throws Exception {
        mvc.perform(delete("/api/products/1"))
                .andExpect(status().isMethodNotAllowed())
                .andExpect(content().contentTypeCompatibleWith(PROBLEM))
                .andExpect(jsonPath("$.type").value("urn:problem:order-payment:method-not-allowed"));
    }

    @Test
    void wrongContentType_returns415ProblemJson() throws Exception {
        mvc.perform(post("/api/products").contentType(MediaType.TEXT_PLAIN).content("name=x"))
                .andExpect(status().isUnsupportedMediaType())
                .andExpect(content().contentTypeCompatibleWith(PROBLEM))
                .andExpect(jsonPath("$.type").value("urn:problem:order-payment:unsupported-media-type"));
    }

    @Test
    void malformedBodyOrTypes_return400MalformedRequest() throws Exception {
        String malformed = "urn:problem:order-payment:malformed-request";
        mvc.perform(post("/api/products").contentType(MediaType.APPLICATION_JSON).content("{not json"))
                .andExpect(status().isBadRequest())
                .andExpect(content().contentTypeCompatibleWith(PROBLEM))
                .andExpect(jsonPath("$.type").value(malformed));
        mvc.perform(post("/api/products").contentType(MediaType.APPLICATION_JSON).content("{\"name\":\"a\",\"price\":\"abc\",\"stock\":1}"))
                .andExpect(status().isBadRequest())
                .andExpect(jsonPath("$.type").value(malformed));
        mvc.perform(post("/api/products").contentType(MediaType.APPLICATION_JSON).content("{\"name\":\"a\",\"price\":10.5,\"stock\":1}"))
                .andExpect(status().isBadRequest())
                .andExpect(jsonPath("$.type").value(malformed));
        mvc.perform(post("/api/products").contentType(MediaType.APPLICATION_JSON))
                .andExpect(status().isBadRequest())
                .andExpect(jsonPath("$.type").value(malformed));
        mvc.perform(get("/api/orders/abc"))
                .andExpect(status().isBadRequest())
                .andExpect(content().contentTypeCompatibleWith(PROBLEM))
                .andExpect(jsonPath("$.type").value(malformed));
    }

    @Test
    void missingNumericField_isValidationFailedNotZero() throws Exception {
        mvc.perform(post("/api/products").contentType(MediaType.APPLICATION_JSON).content("{\"name\":\"a\",\"stock\":1}"))
                .andExpect(status().isBadRequest())
                .andExpect(jsonPath("$.type").value("urn:problem:order-payment:validation-failed"))
                .andExpect(jsonPath("$.errors[0].field").value("price"));
    }
}
package com.example.order;

import static org.hamcrest.Matchers.hasSize;
import static org.hamcrest.Matchers.nullValue;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.content;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.header;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

import com.example.order.support.AbstractIntegrationTest;
import java.time.Duration;
import java.time.Instant;
import org.junit.jupiter.api.Test;
import org.springframework.http.MediaType;

class ProductCouponSmokeTest extends AbstractIntegrationTest {

    @Test
    void createProduct_returns201WithLocation_andGetShowsAvailable() throws Exception {
        var created = api.postProduct(api.objectMapper().createObjectNode()
                        .put("name", "  Keyboard ").put("price", 12000).put("stock", 10))
                .andExpect(status().isCreated())
                .andExpect(jsonPath("$.name").value("Keyboard"))
                .andExpect(jsonPath("$.reserved").value(0))
                .andExpect(jsonPath("$.available").value(10))
                .andReturn();
        String location = created.getResponse().getHeader("Location");
        org.assertj.core.api.Assertions.assertThat(location).matches("/api/products/\\d+");

        mvc.perform(get(location))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.price").value(12000))
                .andExpect(jsonPath("$.stock").value(10))
                .andExpect(jsonPath("$.available").value(10));
    }

    @Test
    void createProduct_withInvalidFields_returns400ValidationFailed() throws Exception {
        api.postProduct(api.objectMapper().createObjectNode().put("name", "   ").put("price", -1).put("stock", -5))
                .andExpect(status().isBadRequest())
                .andExpect(content().contentTypeCompatibleWith(MediaType.APPLICATION_PROBLEM_JSON))
                .andExpect(jsonPath("$.type").value("urn:problem:order-payment:validation-failed"))
                .andExpect(jsonPath("$.errors", hasSize(3)));
    }

    @Test
    void getProduct_unknownId_returns404() throws Exception {
        mvc.perform(get("/api/products/999"))
                .andExpect(status().isNotFound())
                .andExpect(jsonPath("$.type").value("urn:problem:order-payment:product-not-found"))
                .andExpect(jsonPath("$.productId").value(999));
    }

    @Test
    void createAndGetCoupon_roundTripsFieldsWithUsedCountZero() throws Exception {
        Instant from = Instant.parse("2030-01-01T00:00:00Z");
        Instant until = from.plus(Duration.ofDays(30));
        api.postCoupon(api.couponBody("WELCOME10", "RATE", 10, null, null, 100, from, until))
                .andExpect(status().isCreated())
                .andExpect(header().string("Location", "/api/coupons/WELCOME10"))
                .andExpect(jsonPath("$.minOrderAmount").value(0))
                .andExpect(jsonPath("$.maxDiscountAmount").value(nullValue()))
                .andExpect(jsonPath("$.usedCount").value(0));

        mvc.perform(get("/api/coupons/WELCOME10"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.type").value("RATE"))
                .andExpect(jsonPath("$.value").value(10))
                .andExpect(jsonPath("$.totalQuantity").value(100))
                .andExpect(jsonPath("$.validFrom").value("2030-01-01T00:00:00Z"));
    }

    @Test
    void createCoupon_duplicateCode_returns409() throws Exception {
        api.createCoupon("DUP", "FIXED", 1000, null, null, 5);
        Instant now = Instant.now();
        api.postCoupon(api.couponBody("DUP", "FIXED", 1000, null, null, 5, now, now.plusSeconds(60)))
                .andExpect(status().isConflict())
                .andExpect(jsonPath("$.type").value("urn:problem:order-payment:coupon-code-duplicate"))
                .andExpect(jsonPath("$.couponCode").value("DUP"));
    }

    @Test
    void createCoupon_rateAbove100_periodReversedOrUnknownType_return400() throws Exception {
        Instant now = Instant.now();
        api.postCoupon(api.couponBody("R101", "RATE", 101, null, null, 5, now, now.plusSeconds(60)))
                .andExpect(status().isBadRequest())
                .andExpect(jsonPath("$.type").value("urn:problem:order-payment:validation-failed"));
        api.postCoupon(api.couponBody("REV", "FIXED", 10, null, null, 5, now.plusSeconds(60), now))
                .andExpect(status().isBadRequest())
                .andExpect(jsonPath("$.type").value("urn:problem:order-payment:validation-failed"));
        api.postCoupon(api.couponBody("FOO", "PERCENT", 10, null, null, 5, now, now.plusSeconds(60)))
                .andExpect(status().isBadRequest())
                .andExpect(jsonPath("$.type").value("urn:problem:order-payment:malformed-request"));
    }

    @Test
    void getCoupon_unknownCode_returns404() throws Exception {
        mvc.perform(get("/api/coupons/NOPE"))
                .andExpect(status().isNotFound())
                .andExpect(jsonPath("$.type").value("urn:problem:order-payment:coupon-not-found"));
    }
}

