@Configuration
@EnableScheduling
@EnableConfigurationProperties(OrderPaymentProperties.class)
public class AppConfig {

    /** All business "now" values come from this clock (tests replace it with a @Primary mutable clock). */
    @Bean
    public Clock clock() {
        return Clock.systemUTC();
    }
}
package com.example.order.config;

import java.net.URI;
import java.time.Duration;
import org.springframework.boot.context.properties.ConfigurationProperties;
import org.springframework.boot.context.properties.bind.DefaultValue;

/**
 * Bound from {@code order-payment.*}. Invalid values fail the binding, which makes application startup fail
 * (e.g. a malformed or non-positive ORDER_PAYMENT_TTL).
 */
@ConfigurationProperties(prefix = "order-payment")
public record OrderPaymentProperties(
        @DefaultValue("PT15M") Duration ttl,
        @DefaultValue("PT30S") Duration leaseDuration,
        @DefaultValue Gateway gateway,
        @DefaultValue Expiry expiry) {

    public OrderPaymentProperties {
        requirePositive("order-payment.ttl", ttl);
        requirePositive("order-payment.lease-duration", leaseDuration);
        if (gateway == null || expiry == null) {
            throw new IllegalArgumentException("order-payment.gateway / order-payment.expiry must not be null");
        }
        Duration minLease = gateway.connectTimeout().plus(gateway.readTimeout()).multipliedBy(2);
        if (leaseDuration.compareTo(minLease) < 0) {
            throw new IllegalArgumentException(
                    "order-payment.lease-duration must be >= 2 x (connect-timeout + read-timeout) = " + minLease);
        }
    }

    public record Gateway(
            @DefaultValue("http://localhost:8081") String url,
            @DefaultValue("PT2S") Duration connectTimeout,
            @DefaultValue("PT5S") Duration readTimeout) {

        public Gateway {
            if (url == null || url.isBlank()) {
                throw new IllegalArgumentException("order-payment.gateway.url must not be blank");
            }
            try {
                URI uri = URI.create(url);
                String scheme = uri.getScheme();
                if (!uri.isAbsolute() || uri.getHost() == null
                        || !("http".equalsIgnoreCase(scheme) || "https".equalsIgnoreCase(scheme))) {
                    throw new IllegalArgumentException("not an absolute http(s) URI");
                }
            } catch (IllegalArgumentException e) {
                throw new IllegalArgumentException("order-payment.gateway.url is invalid: " + e.getMessage(), e);
            }
            requirePositive("order-payment.gateway.connect-timeout", connectTimeout);
            requirePositive("order-payment.gateway.read-timeout", readTimeout);
        }
    }

    public record Expiry(
            @DefaultValue("true") boolean sweepEnabled,
            @DefaultValue("PT10S") Duration sweepInterval,
            @DefaultValue("100") int batchSize) {

        public Expiry {
            requirePositive("order-payment.expiry.sweep-interval", sweepInterval);
            if (batchSize < 1 || batchSize > 1000) {
                throw new IllegalArgumentException("order-payment.expiry.batch-size must be within 1..1000");
            }
        }
    }

    private static void requirePositive(String name, Duration d) {
        if (d == null || d.isZero() || d.isNegative()) {
            throw new IllegalArgumentException(name + " must be a positive ISO-8601 duration");
        }
    }
}
package com.example.order.order;

import com.example.order.common.FieldErrorDetail;
import com.example.order.common.Problems;
import com.example.order.payment.PayRequest;
import com.example.order.payment.PaymentService;
import jakarta.validation.Valid;
import java.net.URI;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import java.util.regex.Pattern;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RequestParam;
import org.springframework.web.bind.annotation.RestController;

@RestController
@RequestMapping("/api/orders")
public class OrderController {

    static final String USER_HEADER = "X-User-Id";
    static final String KEY_HEADER = "Idempotency-Key";
    static final String REPLAYED_HEADER = "Idempotent-Replayed";
    private static final Pattern KEY_PATTERN = Pattern.compile("^[\\x21-\\x7E]{1,128}$");
    private static final int DEFAULT_PAGE_SIZE = 20;
    private static final int MAX_PAGE_SIZE = 100;

    private final OrderCommandService commands;
    private final OrderQueryService queries;
    private final PaymentService payments;

    public OrderController(OrderCommandService commands, OrderQueryService queries, PaymentService payments) {
        this.commands = commands;
        this.queries = queries;
        this.payments = payments;
    }

    @PostMapping
    public ResponseEntity<OrderResponse> create(
            @RequestHeader(value = USER_HEADER, required = false) String userId,
            @RequestHeader(value = KEY_HEADER, required = false) String idempotencyKey,
            @Valid @RequestBody CreateOrderRequest request) {
        if (userId == null) {
            throw Problems.missingHeader(USER_HEADER);
        }
        if (idempotencyKey == null) {
            throw Problems.missingHeader(KEY_HEADER);
        }
        validateUserId(userId);
        validateKey(idempotencyKey);
        validateNoDuplicateProducts(request);

        OrderCommandService.CreateOutcome outcome = commands.create(userId, idempotencyKey, request);
        ResponseEntity.BodyBuilder response = ResponseEntity.created(URI.create("/api/orders/" + outcome.order().id()));
        if (outcome.replayed()) {
            response.header(REPLAYED_HEADER, "true");
        }
        return response.body(outcome.order());
    }

    @GetMapping("/{id}")
    public OrderResponse get(@PathVariable long id) {
        return queries.get(id);
    }

    @GetMapping
    public OrderPage list(@RequestParam(value = "userId", required = false) String userId,
                          @RequestParam(value = "status", required = false) String status,
                          @RequestParam(value = "size", required = false) String size,
                          @RequestParam(value = "cursor", required = false) String cursor) {
        List<FieldErrorDetail> errors = new ArrayList<>();
        if (userId != null && userId.isBlank()) {
            errors.add(new FieldErrorDetail("userId", "must not be blank"));
        }
        OrderStatus statusFilter = null;
        if (status != null) {
            try {
                statusFilter = OrderStatus.valueOf(status);
            } catch (IllegalArgumentException e) {
                errors.add(new FieldErrorDetail("status", "must be one of " + List.of(OrderStatus.values())));
            }
        }
        int pageSize = DEFAULT_PAGE_SIZE;
        if (size != null) {
            try {
                pageSize = Integer.parseInt(size);
                if (pageSize < 1 || pageSize > MAX_PAGE_SIZE) {
                    errors.add(new FieldErrorDetail("size", "must be between 1 and " + MAX_PAGE_SIZE));
                }
            } catch (NumberFormatException e) {
                errors.add(new FieldErrorDetail("size", "must be an integer between 1 and " + MAX_PAGE_SIZE));
            }
        }
        if (!errors.isEmpty()) {
            throw Problems.validationFailed(errors);
        }
        Long beforeId = cursor == null ? null : Cursor.decode(cursor);
        return queries.list(userId, statusFilter, pageSize, beforeId);
    }

    @PostMapping("/{id}/pay")
    public ResponseEntity<OrderResponse> pay(@PathVariable long id,
                                             @RequestHeader(value = KEY_HEADER, required = false) String idempotencyKey,
                                             @Valid @RequestBody PayRequest request) {
        if (idempotencyKey == null) {
            throw Problems.missingHeader(KEY_HEADER);
        }
        validateKey(idempotencyKey);
        PaymentService.PayOutcome outcome = payments.pay(id, idempotencyKey, request.cardToken());
        ResponseEntity.BodyBuilder response = ResponseEntity.status(HttpStatus.OK);
        if (outcome.replayed()) {
            response.header(REPLAYED_HEADER, "true");
        }
        return response.body(outcome.order());
    }

    @PostMapping("/{id}/cancel")
    public OrderResponse cancel(@PathVariable long id) {
        return commands.cancel(id);
    }

    @PostMapping("/{id}/ship")
    public OrderResponse ship(@PathVariable long id) {
        return commands.ship(id);
    }

    @PostMapping("/{id}/deliver")
    public OrderResponse deliver(@PathVariable long id) {
        return commands.deliver(id);
    }

    private static void validateUserId(String userId) {
        if (userId.isBlank() || userId.length() > 64) {
            throw Problems.validationFailed(USER_HEADER, "must be 1..64 characters and not blank");
        }
    }

    private static void validateKey(String key) {
        if (!KEY_PATTERN.matcher(key).matches()) {
            throw Problems.validationFailed(KEY_HEADER, "must be 1..128 printable ASCII characters without spaces");
        }
    }

    private static void validateNoDuplicateProducts(CreateOrderRequest request) {
        Set<Long> seen = new HashSet<>();
        for (CreateOrderRequest.Item item : request.items()) {
            if (!seen.add(item.productId())) {
                throw Problems.validationFailed("items", "productId " + item.productId() + " appears more than once");
            }
        }
    }
}
package com.example.order.common;

import org.springframework.http.HttpStatus;

/** slug <-> status mapping of 01_api_design.md section 1.1. */
public enum ProblemType {
    VALIDATION_FAILED("validation-failed", HttpStatus.BAD_REQUEST, "Validation failed"),
    MISSING_HEADER("missing-header", HttpStatus.BAD_REQUEST, "Required header is missing"),
    MALFORMED_REQUEST("malformed-request", HttpStatus.BAD_REQUEST, "Malformed request"),
    INVALID_CURSOR("invalid-cursor", HttpStatus.BAD_REQUEST, "Invalid cursor"),
    PRODUCT_NOT_FOUND("product-not-found", HttpStatus.NOT_FOUND, "Product not found"),
    COUPON_NOT_FOUND("coupon-not-found", HttpStatus.NOT_FOUND, "Coupon not found"),
    ORDER_NOT_FOUND("order-not-found", HttpStatus.NOT_FOUND, "Order not found"),
    RESOURCE_NOT_FOUND("resource-not-found", HttpStatus.NOT_FOUND, "Resource not found"),
    METHOD_NOT_ALLOWED("method-not-allowed", HttpStatus.METHOD_NOT_ALLOWED, "Method not allowed"),
    NOT_ACCEPTABLE("not-acceptable", HttpStatus.NOT_ACCEPTABLE, "Not acceptable"),
    UNSUPPORTED_MEDIA_TYPE("unsupported-media-type", HttpStatus.UNSUPPORTED_MEDIA_TYPE, "Unsupported media type"),
    COUPON_CODE_DUPLICATE("coupon-code-duplicate", HttpStatus.CONFLICT, "Coupon code already exists"),
    INSUFFICIENT_STOCK("insufficient-stock", HttpStatus.CONFLICT, "Insufficient stock"),
    INVALID_ORDER_STATE("invalid-order-state", HttpStatus.CONFLICT, "Invalid order state"),
    ORDER_EXPIRED("order-expired", HttpStatus.CONFLICT, "Order expired"),
    IDEMPOTENCY_KEY_CONFLICT("idempotency-key-conflict", HttpStatus.CONFLICT, "Idempotency key conflict"),
    OPERATION_IN_PROGRESS("operation-in-progress", HttpStatus.CONFLICT, "Operation in progress"),
    COUPON_NOT_IN_PERIOD("coupon-not-in-period", HttpStatus.UNPROCESSABLE_ENTITY, "Coupon is not in its valid period"),
    COUPON_MIN_ORDER_NOT_MET("coupon-min-order-not-met", HttpStatus.UNPROCESSABLE_ENTITY, "Minimum order amount not met"),
    COUPON_EXHAUSTED("coupon-exhausted", HttpStatus.UNPROCESSABLE_ENTITY, "Coupon exhausted"),
    PG_GATEWAY_ERROR("pg-gateway-error", HttpStatus.BAD_GATEWAY, "Payment gateway error"),
    PG_GATEWAY_TIMEOUT("pg-gateway-timeout", HttpStatus.GATEWAY_TIMEOUT, "Payment gateway timeout"),
    INTERNAL_ERROR("internal-error", HttpStatus.INTERNAL_SERVER_ERROR, "Internal server error");

    public static final String URN_PREFIX = "urn:problem:order-payment:";

    private final String slug;
    private final HttpStatus status;
    private final String title;

    ProblemType(String slug, HttpStatus status, String title) {
        this.slug = slug;
        this.status = status;
        this.title = title;
    }

    public String slug() {
        return slug;
    }

    public HttpStatus status() {
        return status;
    }

    public String title() {
        return title;
    }

    public String typeUri() {
        return URN_PREFIX + slug;
    }
}
package com.example.order.common;

import jakarta.servlet.http.HttpServletRequest;
import java.net.URI;
import java.util.ArrayList;
import java.util.List;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.http.HttpHeaders;
import org.springframework.http.HttpStatus;
import org.springframework.http.HttpStatusCode;
import org.springframework.http.ProblemDetail;
import org.springframework.http.ResponseEntity;
import org.springframework.lang.Nullable;
import org.springframework.web.HttpMediaTypeNotAcceptableException;
import org.springframework.web.HttpMediaTypeNotSupportedException;
import org.springframework.web.HttpRequestMethodNotSupportedException;
import org.springframework.web.bind.MethodArgumentNotValidException;
import org.springframework.web.bind.MissingRequestHeaderException;
import org.springframework.web.bind.annotation.ExceptionHandler;
import org.springframework.web.bind.annotation.RestControllerAdvice;
import org.springframework.web.context.request.ServletWebRequest;
import org.springframework.web.context.request.WebRequest;
import org.springframework.web.method.annotation.HandlerMethodValidationException;
import org.springframework.web.servlet.NoHandlerFoundException;
import org.springframework.web.servlet.mvc.method.annotation.ResponseEntityExceptionHandler;
import org.springframework.web.servlet.resource.NoResourceFoundException;

/** Renders every error as application/problem+json with the urn:problem:order-payment:{slug} type. */
@RestControllerAdvice
public class GlobalExceptionHandler extends ResponseEntityExceptionHandler {

    private static final Logger log = LoggerFactory.getLogger(GlobalExceptionHandler.class);

    @ExceptionHandler(ApiException.class)
    public ResponseEntity<Object> handleApiException(ApiException ex, HttpServletRequest request) {
        ProblemType type = ex.type();
        ProblemDetail pd = problem(type, type.status(), ex.getMessage(), request.getRequestURI());
        ex.extensions().forEach(pd::setProperty);
        return ResponseEntity.status(type.status()).headers(ex.headers()).body(pd);
    }

    @ExceptionHandler(Exception.class)
    public ResponseEntity<Object> handleUnexpected(Exception ex, HttpServletRequest request) {
        log.error("Unexpected error on {}", request.getRequestURI(), ex);
        ProblemDetail pd = problem(ProblemType.INTERNAL_ERROR, HttpStatus.INTERNAL_SERVER_ERROR,
                "Unexpected error", request.getRequestURI());
        return ResponseEntity.status(HttpStatus.INTERNAL_SERVER_ERROR).body(pd);
    }

    @Override
    protected ResponseEntity<Object> handleExceptionInternal(Exception ex, @Nullable Object body, HttpHeaders headers,
                                                             HttpStatusCode statusCode, WebRequest request) {
        String path = request instanceof ServletWebRequest swr ? swr.getRequest().getRequestURI() : "";
        ProblemType type = typeFor(ex, statusCode);
        ProblemDetail pd = problem(type, statusCode, detailFor(type), path);
        if (ex instanceof MethodArgumentNotValidException manve) {
            List<FieldErrorDetail> errors = new ArrayList<>();
            manve.getBindingResult().getFieldErrors()
                    .forEach(fe -> errors.add(new FieldErrorDetail(fe.getField(), fe.getDefaultMessage())));
            manve.getBindingResult().getGlobalErrors()
                    .forEach(ge -> errors.add(new FieldErrorDetail(ge.getObjectName(), ge.getDefaultMessage())));
            pd.setProperty("errors", errors);
        } else if (ex instanceof HandlerMethodValidationException hmve) {
            List<FieldErrorDetail> errors = new ArrayList<>();
            hmve.getParameterValidationResults().forEach(r -> r.getResolvableErrors().forEach(e ->
                    errors.add(new FieldErrorDetail(r.getMethodParameter().getParameterName(), e.getDefaultMessage()))));
            pd.setProperty("errors", errors);
        } else if (ex instanceof MissingRequestHeaderException mrhe) {
            pd.setProperty("header", mrhe.getHeaderName());
        }
        if (statusCode.is5xxServerError()) {
            log.error("Server error on {}", path, ex);
        }
        return super.handleExceptionInternal(ex, pd, headers, statusCode, request);
    }

    private static ProblemType typeFor(Exception ex, HttpStatusCode status) {
        if (ex instanceof MethodArgumentNotValidException || ex instanceof HandlerMethodValidationException) {
            return ProblemType.VALIDATION_FAILED;
        }
        if (ex instanceof MissingRequestHeaderException) {
            return ProblemType.MISSING_HEADER;
        }
        if (ex instanceof NoResourceFoundException || ex instanceof NoHandlerFoundException) {
            return ProblemType.RESOURCE_NOT_FOUND;
        }
        if (ex instanceof HttpRequestMethodNotSupportedException) {
            return ProblemType.METHOD_NOT_ALLOWED;
        }
        if (ex instanceof HttpMediaTypeNotSupportedException) {
            return ProblemType.UNSUPPORTED_MEDIA_TYPE;
        }
        if (ex instanceof HttpMediaTypeNotAcceptableException) {
            return ProblemType.NOT_ACCEPTABLE;
        }
        if (status.is5xxServerError()) {
            return ProblemType.INTERNAL_ERROR;
        }
        return ProblemType.MALFORMED_REQUEST;
    }

    private static String detailFor(ProblemType type) {
        return switch (type) {
            case VALIDATION_FAILED -> "Request validation failed";
            case MISSING_HEADER -> "A required header is missing";
            case RESOURCE_NOT_FOUND -> "No resource is mapped to this path";
            case METHOD_NOT_ALLOWED -> "The HTTP method is not allowed for this path";
            case UNSUPPORTED_MEDIA_TYPE -> "The request Content-Type is not supported";
            case NOT_ACCEPTABLE -> "The requested response media type is not available";
            case INTERNAL_ERROR -> "Unexpected error";
            default -> "The request is malformed (invalid JSON, missing body or a value of the wrong type)";
        };
    }

    private static ProblemDetail problem(ProblemType type, HttpStatusCode status, String detail, String instance) {
        ProblemDetail pd = ProblemDetail.forStatusAndDetail(status, detail);
        pd.setType(URI.create(type.typeUri()));
        pd.setTitle(type.title());
        if (instance != null && !instance.isEmpty()) {
            try {
                pd.setInstance(URI.create(instance));
            } catch (IllegalArgumentException ignored) {
                // unparsable raw path: leave instance unset rather than failing the error response
            }
        }
        return pd;
    }
}

package com.example.order.payment;

import com.example.order.common.Hashing;
import com.example.order.order.OrderResponse;
import java.util.UUID;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.stereotype.Service;

/**
 * Orchestrates TX-A -> PG call -> TX-C. NOT transactional: the PG call must never run inside a DB
 * transaction (R11). All transactional work lives in PaymentTxService.
 */
@Service
public class PaymentService {

    private static final Logger log = LoggerFactory.getLogger(PaymentService.class);

    public record PayOutcome(OrderResponse order, boolean replayed) {
    }

    private final PaymentTxService tx;
    private final PaymentGatewayClient gateway;

    public PaymentService(PaymentTxService tx, PaymentGatewayClient gateway) {
        this.tx = tx;
        this.gateway = gateway;
    }

    public PayOutcome pay(long orderId, String idempotencyKey, String cardToken) {
        String cardHash = Hashing.sha256Hex(cardToken); // the raw token is never stored or logged
        PaymentTxService.PayBegin begin = tx.beginPayment(orderId, idempotencyKey, cardHash);
        if (begin.replay()) {
            return new PayOutcome(begin.replayedOrder(), true);
        }
        GatewayResult result;
        try {
            result = gateway.charge(orderId, begin.amount(), cardToken, idempotencyKey);
        } catch (GatewayException e) {
            abort(orderId, begin.token(), e);
            throw e.toApiException(orderId);
        } catch (RuntimeException e) {
            abort(orderId, begin.token(), e);
            throw e;
        }
        return new PayOutcome(tx.completePayment(orderId, begin.token(), result), false);
    }

    public OrderResponse refund(long orderId) {
        PaymentTxService.RefundBegin begin = tx.beginRefund(orderId);
        try {
            gateway.refund(begin.pgPaymentId(), "refund-" + orderId);
        } catch (GatewayException e) {
            abort(orderId, begin.token(), e);
            throw e.toApiException(orderId);
        } catch (RuntimeException e) {
            abort(orderId, begin.token(), e);
            throw e;
        }
        return tx.completeRefund(orderId, begin.token());
    }

    private void abort(long orderId, UUID token, RuntimeException cause) {
        log.warn("PG call failed for order {}: {}", orderId, cause.getMessage());
        tx.abortLease(orderId, token, cause.getMessage());
    }
}
package com.example.order.payment;

import com.example.order.common.ApiException;
import com.example.order.common.Problems;
import com.example.order.common.Times;
import com.example.order.config.OrderPaymentProperties;
import com.example.order.order.OrderAction;
import com.example.order.order.OrderAssembler;
import com.example.order.order.OrderRepository;
import com.example.order.order.OrderResponse;
import com.example.order.order.OrderRow;
import com.example.order.order.OrderStateMachine;
import com.example.order.order.OrderStatus;
import com.example.order.order.OrderTransitionService;
import com.example.order.order.ReservationReleaser;
import java.time.Clock;
import java.time.Instant;
import java.util.UUID;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/**
 * The short DB transactions around a PG call (TX-A before, TX-C after). Deliberately a separate bean from
 * PaymentService so the @Transactional proxies apply and the PG call itself stays outside any transaction.
 */
@Service
public class PaymentTxService {

    private static final Logger log = LoggerFactory.getLogger(PaymentTxService.class);

    public record PayBegin(boolean replay, OrderResponse replayedOrder, UUID token, long amount) {
    }

    public record RefundBegin(UUID token, String pgPaymentId) {
    }

    private final OrderRepository orders;
    private final PaymentRepository payments;
    private final OrderAssembler assembler;
    private final OrderTransitionService transitions;
    private final ReservationReleaser releaser;
    private final OrderPaymentProperties props;
    private final Clock clock;

    public PaymentTxService(OrderRepository orders, PaymentRepository payments, OrderAssembler assembler,
                            OrderTransitionService transitions, ReservationReleaser releaser,
                            OrderPaymentProperties props, Clock clock) {
        this.orders = orders;
        this.payments = payments;
        this.assembler = assembler;
        this.transitions = transitions;
        this.releaser = releaser;
        this.props = props;
        this.clock = clock;
    }

    /** TX-A for pay: replay/conflict/state decision, lazy expiry, lease claim, payment row upsert. */
    @Transactional(noRollbackFor = ApiException.class) // keep the lazy expiry when answering order-expired
    public PayBegin beginPayment(long orderId, String idempotencyKey, String cardHash) {
        Instant now = Times.now(clock);
        OrderRow order = loadOrder(orderId);
        PaymentRow payment = payments.findByOrderId(orderId).orElse(null);

        if (payment != null) {
            if (payment.idempotencyKey().equals(idempotencyKey)) {
                if (!payment.requestHash().equals(cardHash)) {
                    throw Problems.idempotencyKeyConflict(
                            "The Idempotency-Key was already used with a different cardToken");
                }
                if (payment.status().isFinalDecision()) {
                    return new PayBegin(true, assembler.assemble(order), null, 0);
                }
            } else {
                if (order.status() == OrderStatus.PENDING_PAYMENT) {
                    throw Problems.idempotencyKeyConflict(
                            "This order already has a payment attempt bound to a different Idempotency-Key");
                }
                throw OrderStateMachine.failureFor(order, OrderAction.PAY, now);
            }
        }

        if (order.status() != OrderStatus.PENDING_PAYMENT) {
            throw OrderStateMachine.failureFor(order, OrderAction.PAY, now);
        }
        if (!order.expiresAt().isAfter(now)) {
            if (!order.leaseActive(now)) {
                transitions.expireIfDue(orderId);
            }
            throw OrderStateMachine.failureFor(loadOrder(orderId), OrderAction.PAY, now);
        }

        UUID token = UUID.randomUUID();
        if (orders.claimPayLease(orderId, token, now, now.plus(props.leaseDuration())) != 1) {
            throw OrderStateMachine.failureFor(loadOrder(orderId), OrderAction.PAY, now);
        }
        payments.upsertInitiated(orderId, idempotencyKey, cardHash, order.totalPrice(), now);
        return new PayBegin(false, null, token, order.totalPrice());
    }

    /** TX-C for pay: APPROVED -> PAID, DECLINED -> PAYMENT_FAILED (+ stock/coupon give-back). */
    @Transactional
    public OrderResponse completePayment(long orderId, UUID token, GatewayResult result) {
        Instant now = Times.now(clock);
        OrderStatus target = result.approved() ? OrderStatus.PAID : OrderStatus.PAYMENT_FAILED;
        if (orders.completePayment(orderId, target, token, now) != 1) {
            log.error("Payment completion lost the lease for order {} (PG result {}); manual reconciliation needed",
                    orderId, target);
            throw Problems.operationInProgress("PAY");
        }
        if (result.approved()) {
            payments.markApproved(orderId, result.paymentId(), now);
        } else {
            releaser.release(orderId, now);
            payments.markDeclined(orderId, now);
        }
        return assembler.load(orderId);
    }

    /** TX-C for a gateway failure: only drop the lease, keep the order PENDING_PAYMENT / PAID. */
    @Transactional
    public void abortLease(long orderId, UUID token, String error) {
        Instant now = Times.now(clock);
        orders.releaseLease(orderId, token, now);
        payments.recordError(orderId, error, now);
    }

    /** TX-A for refund (cancel on PAID). */
    @Transactional
    public RefundBegin beginRefund(long orderId) {
        Instant now = Times.now(clock);
        UUID token = UUID.randomUUID();
        if (orders.claimRefundLease(orderId, token, now, now.plus(props.leaseDuration())) != 1) {
            throw OrderStateMachine.failureFor(loadOrder(orderId), OrderAction.CANCEL, now);
        }
        PaymentRow payment = payments.findByOrderId(orderId)
                .orElseThrow(() -> new IllegalStateException("PAID order without payment row: " + orderId));
        if (payment.pgPaymentId() == null) {
            throw new IllegalStateException("PAID order without pg payment id: " + orderId);
        }
        return new RefundBegin(token, payment.pgPaymentId());
    }

    /** TX-C for refund: PAID -> REFUNDED with stock/coupon give-back. */
    @Transactional
    public OrderResponse completeRefund(long orderId, UUID token) {
        Instant now = Times.now(clock);
        if (orders.completeRefund(orderId, token, now) != 1) {
            log.error("Refund completion lost the lease for order {}; manual reconciliation needed", orderId);
            throw Problems.operationInProgress("REFUND");
        }
        releaser.release(orderId, now);
        payments.markRefunded(orderId, now);
        return assembler.load(orderId);
    }

    private OrderRow loadOrder(long orderId) {
        return orders.findById(orderId).orElseThrow(() -> Problems.orderNotFound(orderId));
    }
}
package com.example.order.payment;

import com.example.order.config.OrderPaymentProperties;
import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import java.io.IOException;
import java.net.SocketTimeoutException;
import java.net.http.HttpClient;
import java.net.http.HttpTimeoutException;
import java.util.LinkedHashMap;
import java.util.Map;
import org.springframework.http.MediaType;
import org.springframework.http.client.JdkClientHttpRequestFactory;
import org.springframework.stereotype.Component;
import org.springframework.web.client.RestClient;
import org.springframework.web.client.RestClientException;

/**
 * External PG over HTTP. Never retries internally. Must be called outside any DB transaction.
 * Timeouts -> GatewayException(TIMEOUT); everything else abnormal -> GatewayException(ERROR).
 */
@Component
public class PaymentGatewayClient {

    private final RestClient client;
    private final ObjectMapper objectMapper;

    public PaymentGatewayClient(RestClient.Builder builder, ObjectMapper objectMapper, OrderPaymentProperties props) {
        HttpClient http = HttpClient.newBuilder()
                .version(HttpClient.Version.HTTP_1_1)
                .connectTimeout(props.gateway().connectTimeout())
                .build();
        JdkClientHttpRequestFactory factory = new JdkClientHttpRequestFactory(http);
        factory.setReadTimeout(props.gateway().readTimeout());
        this.client = builder.baseUrl(props.gateway().url()).requestFactory(factory).build();
        this.objectMapper = objectMapper;
    }

    /** POST /v1/payments. */
    public GatewayResult charge(long orderId, long amount, String cardToken, String idempotencyKey) {
        Map<String, Object> body = new LinkedHashMap<>();
        body.put("orderId", orderId);
        body.put("amount", amount);
        body.put("cardToken", cardToken);
        JsonNode json = post(client.post().uri("/v1/payments").header("Idempotency-Key", idempotencyKey), body);
        String status = text(json, "status");
        String paymentId = text(json, "paymentId");
        if ("APPROVED".equals(status)) {
            if (paymentId == null || paymentId.isBlank() || paymentId.length() > 128) {
                throw new GatewayException(GatewayException.Kind.ERROR, "PG APPROVED without a usable paymentId", null);
            }
            return new GatewayResult(paymentId, true);
        }
        if ("DECLINED".equals(status)) {
            return new GatewayResult(paymentId, false);
        }
        throw new GatewayException(GatewayException.Kind.ERROR, "PG returned unexpected status", null);
    }

    /** POST /v1/payments/{paymentId}/refund. */
    public GatewayResult refund(String paymentId, String idempotencyKey) {
        JsonNode json = post(client.post().uri("/v1/payments/{paymentId}/refund", paymentId)
                .header("Idempotency-Key", idempotencyKey), null);
        if (!"REFUNDED".equals(text(json, "status"))) {
            throw new GatewayException(GatewayException.Kind.ERROR, "PG returned unexpected refund status", null);
        }
        return new GatewayResult(paymentId, true);
    }

    private JsonNode post(RestClient.RequestBodySpec spec, Object body) {
        try {
            RestClient.RequestBodySpec prepared = spec.contentType(MediaType.APPLICATION_JSON).accept(MediaType.APPLICATION_JSON);
            if (body != null) {
                prepared = prepared.body(body);
            }
            return prepared.exchange((request, response) -> {
                int code = response.getStatusCode().value();
                if (code < 200 || code >= 300) {
                    throw new GatewayException(GatewayException.Kind.ERROR, "PG responded with HTTP " + code, null);
                }
                try {
                    JsonNode node = objectMapper.readTree(response.getBody());
                    if (node == null || !node.isObject()) {
                        throw new GatewayException(GatewayException.Kind.ERROR, "PG response is not a JSON object", null);
                    }
                    return node;
                } catch (IOException e) {
                    throw classify(e);
                }
            });
        } catch (GatewayException e) {
            throw e;
        } catch (RestClientException e) {
            throw classify(e);
        }
    }

    private static GatewayException classify(Throwable t) {
        for (Throwable c = t; c != null; c = c.getCause()) {
            if (c instanceof SocketTimeoutException || c instanceof HttpTimeoutException) {
                return new GatewayException(GatewayException.Kind.TIMEOUT, "PG call timed out", t);
            }
        }
        return new GatewayException(GatewayException.Kind.ERROR, "PG call failed: " + t.getClass().getSimpleName(), t);
    }

    private static String text(JsonNode node, String field) {
        JsonNode v = node.get(field);
        return v == null || v.isNull() ? null : v.asText();
    }
}
package com.example.order.order;

import com.example.order.common.Hashing;
import com.example.order.common.Problems;
import com.example.order.payment.PaymentService;
import java.util.Comparator;
import java.util.Optional;
import java.util.stream.Collectors;
import org.springframework.stereotype.Service;

/** Non-transactional orchestration: order creation idempotency loop and cancel dispatch. */
@Service
public class OrderCommandService {

    private static final int MAX_CREATE_ATTEMPTS = 3;

    public record CreateOutcome(OrderResponse order, boolean replayed) {
    }

    private final OrderRepository orders;
    private final OrderCreator creator;
    private final OrderAssembler assembler;
    private final OrderTransitionService transitions;
    private final PaymentService payments;

    public OrderCommandService(OrderRepository orders, OrderCreator creator, OrderAssembler assembler,
                               OrderTransitionService transitions, PaymentService payments) {
        this.orders = orders;
        this.creator = creator;
        this.assembler = assembler;
        this.transitions = transitions;
        this.payments = payments;
    }

    public CreateOutcome create(String userId, String idempotencyKey, CreateOrderRequest request) {
        String hash = requestHash(request);
        for (int attempt = 0; attempt < MAX_CREATE_ATTEMPTS; attempt++) {
            Optional<OrderRow> existing = orders.findByUserAndKey(userId, idempotencyKey);
            if (existing.isPresent()) {
                if (!hash.equals(existing.get().requestHash())) {
                    throw Problems.idempotencyKeyConflict(
                            "The Idempotency-Key was already used with a different request body");
                }
                return new CreateOutcome(assembler.assemble(existing.get()), true);
            }
            Optional<Long> created = creator.create(userId, idempotencyKey, hash, request);
            if (created.isPresent()) {
                return new CreateOutcome(assembler.load(created.get()), false);
            }
            // a concurrent request with the same key committed first: loop to replay / conflict
        }
        throw new IllegalStateException("Could not resolve idempotent order creation");
    }

    public OrderResponse cancel(long orderId) {
        OrderRow current = orders.findById(orderId).orElseThrow(() -> Problems.orderNotFound(orderId));
        if (current.status() == OrderStatus.PAID) {
            return payments.refund(orderId);
        }
        return transitions.cancelPending(orderId); // non-pending statuses are mapped to 409 inside
    }

    public OrderResponse ship(long orderId) {
        return transitions.ship(orderId);
    }

    public OrderResponse deliver(long orderId) {
        return transitions.deliver(orderId);
    }

    /** SHA-256 of "items=<productId>:<qty>,...(productId asc);coupon=<code or empty>". */
    static String requestHash(CreateOrderRequest request) {
        String items = request.items().stream()
                .sorted(Comparator.comparingLong(CreateOrderRequest.Item::productId))
                .map(i -> i.productId() + ":" + i.quantity())
                .collect(Collectors.joining(","));
        return Hashing.sha256Hex("items=" + items + ";coupon=" + (request.couponCode() == null ? "" : request.couponCode()));
    }
}

package com.example.order.order;

import com.example.order.common.ApiException;
import com.example.order.common.Problems;
import java.time.Instant;

/**
 * Maps "a conditional UPDATE claimed 0 rows" to the 409 of 01_api_design.md section 3.3,
 * given the freshly re-read order.
 */
public final class OrderStateMachine {

    private OrderStateMachine() {
    }

    public static ApiException failureFor(OrderRow current, OrderAction action, Instant now) {
        boolean leaseActive = current.leaseActive(now);
        if (action == OrderAction.PAY || action == OrderAction.CANCEL) {
            if (current.status() == OrderStatus.EXPIRED) {
                return Problems.orderExpired(current.expiresAt());
            }
            if (current.status() == OrderStatus.PENDING_PAYMENT && !current.expiresAt().isAfter(now)) {
                return leaseActive
                        ? Problems.operationInProgress(current.leaseKind())
                        : Problems.orderExpired(current.expiresAt());
            }
        }
        if (leaseActive && action.canStartFrom(current.status())) {
            return Problems.operationInProgress(current.leaseKind());
        }
        return Problems.invalidOrderState(current.status(), action);
    }
}
package com.example.order.order;

import java.util.EnumMap;
import java.util.EnumSet;
import java.util.Map;
import java.util.Set;

/** The single place that defines which status transitions exist (R15). */
public enum OrderStatus {
    PENDING_PAYMENT, PAID, PAYMENT_FAILED, EXPIRED, CANCELLED, REFUNDED, SHIPPED, DELIVERED;

    private static final Map<OrderStatus, Set<OrderStatus>> ALLOWED = new EnumMap<>(OrderStatus.class);

    static {
        ALLOWED.put(PENDING_PAYMENT, EnumSet.of(PAID, PAYMENT_FAILED, EXPIRED, CANCELLED));
        ALLOWED.put(PAID, EnumSet.of(SHIPPED, REFUNDED));
        ALLOWED.put(SHIPPED, EnumSet.of(DELIVERED));
        for (OrderStatus s : values()) {
            ALLOWED.putIfAbsent(s, EnumSet.noneOf(OrderStatus.class));
        }
    }

    public boolean canTransitionTo(OrderStatus target) {
        return ALLOWED.get(this).contains(target);
    }

    /** Guard used by every conditional-UPDATE method before issuing its SQL (programming-error check). */
    public static void requireTransition(OrderStatus from, OrderStatus to) {
        if (!from.canTransitionTo(to)) {
            throw new IllegalStateException("Illegal order transition " + from + " -> " + to);
        }
    }
}
package com.example.order.order;

import com.example.order.common.ApiException;
import com.example.order.common.Problems;
import com.example.order.common.Times;
import com.example.order.product.StockRepository;
import java.time.Clock;
import java.time.Instant;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/**
 * Transactional state transitions that need no PG call: expire, cancel(pending), ship, deliver.
 * Each transition is a conditional UPDATE (claim); side effects run only when the claim affected 1 row.
 */
@Service
public class OrderTransitionService {

    private final OrderRepository orders;
    private final OrderAssembler assembler;
    private final ReservationReleaser releaser;
    private final StockRepository stock;
    private final Clock clock;

    public OrderTransitionService(OrderRepository orders, OrderAssembler assembler, ReservationReleaser releaser,
                                  StockRepository stock, Clock clock) {
        this.orders = orders;
        this.assembler = assembler;
        this.releaser = releaser;
        this.stock = stock;
        this.clock = clock;
    }

    /** Expires one order if (and only if) it is due and not under an active lease. Safe to call concurrently. */
    @Transactional
    public boolean expireIfDue(long orderId) {
        Instant now = Times.now(clock);
        if (orders.claimExpire(orderId, now) != 1) {
            return false;
        }
        releaser.release(orderId, now);
        return true;
    }

    /** cancel on PENDING_PAYMENT. Keeps the lazy expiry commit when it then answers order-expired. */
    @Transactional(noRollbackFor = ApiException.class)
    public OrderResponse cancelPending(long orderId) {
        Instant now = Times.now(clock);
        OrderRow current = orders.findById(orderId).orElseThrow(() -> Problems.orderNotFound(orderId));
        if (current.status() != OrderStatus.PENDING_PAYMENT) {
            throw OrderStateMachine.failureFor(current, OrderAction.CANCEL, now);
        }
        if (!current.expiresAt().isAfter(now)) {
            expireIfDue(orderId);
            throw OrderStateMachine.failureFor(reload(orderId), OrderAction.CANCEL, now);
        }
        if (orders.claimCancel(orderId, now) != 1) {
            throw OrderStateMachine.failureFor(reload(orderId), OrderAction.CANCEL, now);
        }
        releaser.release(orderId, now);
        return assembler.load(orderId);
    }

    @Transactional
    public OrderResponse ship(long orderId) {
        Instant now = Times.now(clock);
        if (orders.claimShip(orderId, now) != 1) {
            throw OrderStateMachine.failureFor(reload(orderId), OrderAction.SHIP, now);
        }
        for (OrderItemRow item : releaser.sortedItems(orderId)) {
            if (!stock.commitShip(item.productId(), item.quantity(), now)) {
                throw new IllegalStateException("Stock invariant violated shipping product " + item.productId()
                        + " for order " + orderId);
            }
        }
        return assembler.load(orderId);
    }

    @Transactional
    public OrderResponse deliver(long orderId) {
        Instant now = Times.now(clock);
        if (orders.claimDeliver(orderId, now) != 1) {
            throw OrderStateMachine.failureFor(reload(orderId), OrderAction.DELIVER, now);
        }
        return assembler.load(orderId);
    }

    private OrderRow reload(long orderId) {
        return orders.findById(orderId).orElseThrow(() -> Problems.orderNotFound(orderId));
    }
}
package com.example.order.order;

import com.example.order.common.Problems;
import com.example.order.common.Times;
import com.example.order.config.OrderPaymentProperties;
import com.example.order.coupon.Coupon;
import com.example.order.coupon.CouponRepository;
import com.example.order.coupon.CouponUsageRepository;
import com.example.order.coupon.DiscountCalculator;
import com.example.order.product.StockRepository;
import java.time.Clock;
import java.time.Instant;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.Map;
import java.util.Optional;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/**
 * One transaction: order claim INSERT -> coupon rule pre-check -> stock reservation (id asc) -> coupon claim
 * -> items. Any failure rolls everything back (the idempotency key is then not consumed).
 */
@Service
public class OrderCreator {

    private final OrderRepository orders;
    private final StockRepository stock;
    private final CouponRepository coupons;
    private final CouponUsageRepository couponUsage;
    private final OrderPaymentProperties props;
    private final Clock clock;

    public OrderCreator(OrderRepository orders, StockRepository stock, CouponRepository coupons,
                        CouponUsageRepository couponUsage, OrderPaymentProperties props, Clock clock) {
        this.orders = orders;
        this.stock = stock;
        this.coupons = coupons;
        this.couponUsage = couponUsage;
        this.props = props;
        this.clock = clock;
    }

    /** @return the new order id, or empty when the (user, key) pair already has an order (caller replays). */
    @Transactional
    public Optional<Long> create(String userId, String idempotencyKey, String requestHash, CreateOrderRequest request) {
        Instant now = Times.now(clock);
        List<CreateOrderRequest.Item> requested = request.items();

        Map<Long, Long> prices = stock.findPrices(requested.stream().map(CreateOrderRequest.Item::productId).toList());
        long subtotal = 0;
        List<OrderItemRow> lines = new ArrayList<>();
        int lineNo = 1;
        for (CreateOrderRequest.Item item : requested) {
            Long price = prices.get(item.productId());
            if (price == null) {
                throw Problems.productNotFound(item.productId());
            }
            subtotal += price * item.quantity();
            lines.add(new OrderItemRow(0, lineNo++, item.productId(), item.quantity(), price));
        }

        Coupon coupon = null;
        if (request.couponCode() != null) {
            coupon = coupons.findByCode(request.couponCode())
                    .orElseThrow(() -> Problems.couponNotFound(request.couponCode()));
        }

        Optional<Long> inserted = orders.insertIfAbsent(userId, coupon == null ? null : coupon.getId(),
                coupon == null ? null : coupon.getCode(), subtotal, idempotencyKey, requestHash, now,
                now.plus(props.ttl()));
        if (inserted.isEmpty()) {
            return Optional.empty();
        }
        long orderId = inserted.get();

        if (coupon != null) {
            precheckCoupon(coupon, subtotal, now);
        }

        lines.stream().sorted(Comparator.comparingLong(OrderItemRow::productId)).forEach(line -> {
            if (!stock.reserve(line.productId(), line.quantity(), now)) {
                throw Problems.insufficientStock(line.productId(), line.quantity(), stock.available(line.productId()));
            }
        });

        if (coupon != null) {
            if (!couponUsage.tryUse(coupon.getId(), now)) {
                boolean inPeriod = !now.isBefore(coupon.getValidFrom()) && !now.isAfter(coupon.getValidUntil());
                throw inPeriod ? Problems.couponExhausted(coupon.getCode())
                        : Problems.couponNotInPeriod(coupon.getCode());
            }
            long discount = DiscountCalculator.calculate(coupon, subtotal);
            orders.applyDiscount(orderId, discount, subtotal - discount, now);
        }

        orders.insertItems(orderId, lines);
        return Optional.of(orderId);
    }

    private static void precheckCoupon(Coupon coupon, long subtotal, Instant now) {
        if (now.isBefore(coupon.getValidFrom()) || now.isAfter(coupon.getValidUntil())) {
            throw Problems.couponNotInPeriod(coupon.getCode());
        }
        if (subtotal < coupon.getMinOrderAmount()) {
            throw Problems.couponMinOrderNotMet(coupon.getCode(), coupon.getMinOrderAmount(), subtotal);
        }
        if (coupon.getUsedCount() >= coupon.getTotalQuantity()) {
            throw Problems.couponExhausted(coupon.getCode());
        }
    }
}
package com.example.order.order;

import com.example.order.common.Times;
import com.example.order.config.OrderPaymentProperties;
import java.time.Clock;
import java.util.List;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.stereotype.Component;

/** Batch expiry. Each order is expired in its own transaction; overlapping runs/instances are harmless. */
@Component
public class OrderExpirySweeper {

    private static final Logger log = LoggerFactory.getLogger(OrderExpirySweeper.class);
    private static final int MAX_BATCHES_PER_RUN = 10;

    private final OrderRepository orders;
    private final OrderTransitionService transitions;
    private final OrderPaymentProperties props;
    private final Clock clock;

    public OrderExpirySweeper(OrderRepository orders, OrderTransitionService transitions,
                              OrderPaymentProperties props, Clock clock) {
        this.orders = orders;
        this.transitions = transitions;
        this.props = props;
        this.clock = clock;
    }

    /** @return number of orders this run actually expired */
    public int sweepOnce() {
        int expired = 0;
        for (int batch = 0; batch < MAX_BATCHES_PER_RUN; batch++) {
            List<Long> due = orders.findDueIds(Times.now(clock), null, props.expiry().batchSize());
            for (Long id : due) {
                try {
                    if (transitions.expireIfDue(id)) {
                        expired++;
                    }
                } catch (RuntimeException e) {
                    log.error("Expiry failed for order {}", id, e);
                }
            }
            if (due.size() < props.expiry().batchSize()) {
                break;
            }
        }
        return expired;
    }
}

package com.example.order.order;

import java.util.EnumSet;
import java.util.Locale;
import java.util.Set;

/** Client-facing order operations and the statuses each can start from. */
public enum OrderAction {
    PAY(EnumSet.of(OrderStatus.PENDING_PAYMENT)),
    CANCEL(EnumSet.of(OrderStatus.PENDING_PAYMENT, OrderStatus.PAID)),
    SHIP(EnumSet.of(OrderStatus.PAID)),
    DELIVER(EnumSet.of(OrderStatus.SHIPPED));

    private final Set<OrderStatus> sources;

    OrderAction(Set<OrderStatus> sources) {
        this.sources = sources;
    }

    public boolean canStartFrom(OrderStatus status) {
        return sources.contains(status);
    }

    public String wireName() {
        return name().toLowerCase(Locale.ROOT);
    }
}
package com.example.order.common;

import com.example.order.order.OrderAction;
import com.example.order.order.OrderStatus;
import java.time.Instant;
import java.util.List;

/** Factory for every ApiException used by the services. */
public final class Problems {

    private Problems() {
    }

    public static ApiException validationFailed(List<FieldErrorDetail> errors) {
        return new ApiException(ProblemType.VALIDATION_FAILED, "Request validation failed").with("errors", errors);
    }

    public static ApiException validationFailed(String field, String message) {
        return validationFailed(List.of(new FieldErrorDetail(field, message)));
    }

    public static ApiException missingHeader(String header) {
        return new ApiException(ProblemType.MISSING_HEADER, "Required header '" + header + "' is missing")
                .with("header", header);
    }

    public static ApiException invalidCursor() {
        return new ApiException(ProblemType.INVALID_CURSOR, "The cursor is invalid");
    }

    public static ApiException productNotFound(long productId) {
        return new ApiException(ProblemType.PRODUCT_NOT_FOUND, "Product " + productId + " was not found")
                .with("productId", productId);
    }

    public static ApiException couponNotFound(String code) {
        return new ApiException(ProblemType.COUPON_NOT_FOUND, "Coupon '" + code + "' was not found")
                .with("couponCode", code);
    }

    public static ApiException orderNotFound(long orderId) {
        return new ApiException(ProblemType.ORDER_NOT_FOUND, "Order " + orderId + " was not found")
                .with("orderId", orderId);
    }

    public static ApiException couponCodeDuplicate(String code) {
        return new ApiException(ProblemType.COUPON_CODE_DUPLICATE, "Coupon code '" + code + "' already exists")
                .with("couponCode", code);
    }

    public static ApiException insufficientStock(long productId, int requested, int available) {
        return new ApiException(ProblemType.INSUFFICIENT_STOCK, "Not enough stock for product " + productId)
                .with("productId", productId).with("requested", requested).with("available", available);
    }

    public static ApiException invalidOrderState(OrderStatus current, OrderAction action) {
        return new ApiException(ProblemType.INVALID_ORDER_STATE,
                "Cannot " + action.wireName() + " an order in status " + current)
                .with("currentStatus", current.name()).with("action", action.wireName());
    }

    public static ApiException orderExpired(Instant expiresAt) {
        return new ApiException(ProblemType.ORDER_EXPIRED, "The order has expired")
                .with("expiresAt", expiresAt);
    }

    public static ApiException idempotencyKeyConflict(String detail) {
        return new ApiException(ProblemType.IDEMPOTENCY_KEY_CONFLICT, detail);
    }

    public static ApiException operationInProgress(String operation) {
        return new ApiException(ProblemType.OPERATION_IN_PROGRESS,
                "Another operation on this order is in progress; retry shortly")
                .with("operation", operation).header("Retry-After", "1");
    }

    public static ApiException couponNotInPeriod(String code) {
        return new ApiException(ProblemType.COUPON_NOT_IN_PERIOD, "Coupon '" + code + "' is not in its valid period")
                .with("couponCode", code);
    }

    public static ApiException couponMinOrderNotMet(String code, long minOrderAmount, long subtotal) {
        return new ApiException(ProblemType.COUPON_MIN_ORDER_NOT_MET,
                "Order subtotal is below the minimum order amount of coupon '" + code + "'")
                .with("couponCode", code).with("minOrderAmount", minOrderAmount).with("subtotal", subtotal);
    }

    public static ApiException couponExhausted(String code) {
        return new ApiException(ProblemType.COUPON_EXHAUSTED, "Coupon '" + code + "' has no remaining quantity")
                .with("couponCode", code);
    }

    public static ApiException gatewayError(long orderId, String detail) {
        return new ApiException(ProblemType.PG_GATEWAY_ERROR, detail)
                .with("orderId", orderId).with("retryable", true);
    }

    public static ApiException gatewayTimeout(long orderId, String detail) {
        return new ApiException(ProblemType.PG_GATEWAY_TIMEOUT, detail)
                .with("orderId", orderId).with("retryable", true);
    }
}
package com.example.order.order;

import com.example.order.common.Problems;
import com.example.order.common.Times;
import java.time.Clock;
import java.time.Instant;
import java.util.List;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.stereotype.Service;

/** Reads with lazy expiry: a due PENDING_PAYMENT order is really expired before it is shown. */
@Service
public class OrderQueryService {

    private static final Logger log = LoggerFactory.getLogger(OrderQueryService.class);
    private static final int LAZY_SWEEP_LIMIT = 500;

    private final OrderRepository orders;
    private final OrderAssembler assembler;
    private final OrderTransitionService transitions;
    private final Clock clock;

    public OrderQueryService(OrderRepository orders, OrderAssembler assembler, OrderTransitionService transitions,
                             Clock clock) {
        this.orders = orders;
        this.assembler = assembler;
        this.transitions = transitions;
        this.clock = clock;
    }

    public OrderResponse get(long id) {
        Instant now = Times.now(clock);
        OrderRow row = orders.findById(id).orElseThrow(() -> Problems.orderNotFound(id));
        if (row.status() == OrderStatus.PENDING_PAYMENT && !row.expiresAt().isAfter(now)
                && transitions.expireIfDue(id)) {
            row = orders.findById(id).orElseThrow(() -> Problems.orderNotFound(id));
        }
        return assembler.assemble(row);
    }

    public OrderPage list(String userId, OrderStatus status, int size, Long beforeId) {
        Instant now = Times.now(clock);
        if (status == null || status == OrderStatus.PENDING_PAYMENT || status == OrderStatus.EXPIRED) {
            for (Long dueId : orders.findDueIds(now, userId, LAZY_SWEEP_LIMIT)) {
                try {
                    transitions.expireIfDue(dueId);
                } catch (RuntimeException e) {
                    log.warn("Lazy expiry failed for order {}", dueId, e);
                }
            }
        }
        List<OrderRow> rows = orders.list(userId, status, beforeId, size + 1);
        boolean hasMore = rows.size() > size;
        List<OrderRow> page = hasMore ? rows.subList(0, size) : rows;
        String next = hasMore ? Cursor.encode(page.get(page.size() - 1).id()) : null;
        return new OrderPage(assembler.assemble(page), next);
    }
}
package com.example.order.order;

import com.example.order.common.Problems;
import java.nio.charset.StandardCharsets;
import java.util.Base64;
import java.util.regex.Pattern;

/** Opaque cursor: Base64URL(no padding) of "v1:" + lastId. */
public final class Cursor {

    private static final Pattern PAYLOAD = Pattern.compile("^v1:[1-9][0-9]{0,18}$");

    private Cursor() {
    }

    public static String encode(long lastId) {
        return Base64.getUrlEncoder().withoutPadding().encodeToString(("v1:" + lastId).getBytes(StandardCharsets.UTF_8));
    }

    public static long decode(String cursor) {
        try {
            byte[] raw = Base64.getUrlDecoder().decode(cursor);
            String payload = new String(raw, StandardCharsets.UTF_8);
            if (!PAYLOAD.matcher(payload).matches()) {
                throw Problems.invalidCursor();
            }
            long id = Long.parseLong(payload.substring(3));
            if (!encode(id).equals(cursor)) { // reject non-canonical encodings
                throw Problems.invalidCursor();
            }
            return id;
        } catch (IllegalArgumentException e) { // bad base64 or Long overflow
            throw Problems.invalidCursor();
        }
    }
}
package com.example.order.coupon;

/** Integer-only discount rule (01_api_design.md section 3.2). */
public final class DiscountCalculator {

    private DiscountCalculator() {
    }

    public static long calculate(CouponType type, long value, Long maxDiscountAmount, long subtotal) {
        long raw = type == CouponType.FIXED ? value : (subtotal * value) / 100; // RATE: floor
        if (maxDiscountAmount != null && maxDiscountAmount > 0) {
            raw = Math.min(raw, maxDiscountAmount);
        }
        return Math.min(raw, subtotal);
    }

    public static long calculate(Coupon coupon, long subtotal) {
        return calculate(coupon.getType(), coupon.getValue(), coupon.getMaxDiscountAmount(), subtotal);
    }
}
